quests[7508] = { id = 7508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden von Quel'Serrar", description = "Wenn Ihr diese Aufgabe annehmen wollt, zeigt Lydros die glanzlose Klinge.", sourceObjective = "Bringt dem Hüter des Wissens Lydros, die stumpfe und glanzlose Elfenklinge.", progress = "Sehr gut, lasst uns beginnen...", completion = "Solltet Ihr es schaffen in den Hort des Drachen einzudringen, die Klinge unter ihrem feurigen Atem zu erhitzen und sie in ihrem Blut zu härten, werde ich die Klinge für Euch binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[7509] = { id = 7509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden von Quel'Serrar", description = "Bringt das uralte, noch unerhitzte Schwert in Onyxias Hort und tretet ihr im Kampf gegenüber.\n\nNur mit einem Trick werdet Ihr es schaffen die Klinge zu erhitzen, also hört gut zu. Im Kampf wird Sie mit Sicherheit nichts unversucht lassen, um Euch mit ihrem Feueratem einzuäschern. Legt die Klinge irgendwo in der Nähe von Onyxia ab und hofft, dass ihr feuriger Atem diese Klinge erhitzt. Sollte es klappen und Ihr noch am Leben sein, hebt die dann erhitzte uralte Klinge wieder auf und erledigt den Drachen.\n\nRammt anschließend die noch heiße Klinge in den schwelenden Drachenkörper, um dadurch eine behandelte uralte Klinge zu erhalten.", sourceObjective = "Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge.\n\nZuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein.", progress = "Eines Tages wird vielleicht wieder jemand die Prismatische Klinge führen.", completion = "<Lydros murmelt etwas Unverständliches.>\n\nWie versprochen {class}, die Klinge von Quel'Serrar.", sourceObjectiveStatus = "unverified-source-field" }
quests[7521] = { id = 7521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donneraan der Windsucher", description = "Ich habe Euch alles gesagt was ich weiß, {name}. Es ist nun Eure Aufgabe Elementium zu finden. Ihr seid es, der die körperliche Form des Feuerfürsten zerstören muss.\n\nGewinnt dadurch den Segen von Donneraan.", sourceObjective = "Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7522] = { id = 7522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Gefäßes", description = "Untersucht das Gefäß der Wiedergeburt, Sterblicher. Mit seiner Hilfe soll der Windsucher wieder auferstehen!", sourceObjective = "Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian.", sourceObjectiveStatus = "unverified-source-field" }
quests[7541] = { id = 7541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst an der Horde", sourceObjective = "Unsere Gelehrten werden einige Zeit brauchen, um den Anhänger, den Ihr uns gebracht habt, zu studieren. Allerdings möchte ich Euch für Euren Dienst an der Horde eine kleine Belohnung geben.\n\nDanke, {name}.  Eure Taten ehren Euch und uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[7561] = { id = 7561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerzorn erwache!", description = "Ihr habt den Windsucher bezwungen. Nehmt die schlummernde Klinge und die Materialen, die Ihr Demitrian für seinen Verrat geliefert habt, und zwingt den verlogenen Schuft, Donnerzorn zu erwecken.", sourceObjective = "Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[7562] = { id = 7562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'zul Bloodbringer", description = "{name}, Eure Studien der dunklen Künste sind sehr eingehend. Euer Einfluss auf die Kräfte der jenseitigen Welt ist sehr stark geworden... ich denke Ihr seid nun bereit eines der berüchtigten Schreckensrösser an Euch zu binden.\n\nDas Ritual zum Beschwören eines dieser Biester erfordert große Macht und Ressourcen, doch wenn Ihr solch ein episches Reittier beherrschen wollt, sprecht mit Meister Mor'zul Bloodbringer. Er hat sein Lager nahe des Altars der Stürme in der brennenden Steppe aufgeschlagen.\n\nGeht, {name}. Diese Aufgabe wird sehr gefährlich werden, aber ein Hexenmeister von Eurer Größe sollte sich nicht vor Gefahr fürchten.", sourceObjective = "Sprecht mit Mor'zul Bloodbringer in der brennenden Steppe.", completion = "Seid gegrüßt, {name}. Seid Ihr wie ich gekommen, um hier am Altar der Stürme zu studieren? Vielleicht um seine Energien für einen geheimen Zweck zu nutzen...\n\nOder seid Ihr vielleicht sogar hier, um mit mir zu sprechen? Ja, ich denke das seid Ihr.\n\nIhr wollt also ein Schreckensross beherrschen? Diese Aufgabe ist nicht einfach. Das wird Euch eine nicht unerhebliche Menge an Blut kosten... und natürlich auch an Gold. Doch ein Schreckensross aus Xoroth ist einen solchen Aufwand mehr als wert. Also wenn Ihr interessiert seid, hört zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[7563] = { id = 7563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochendes Blut", description = "Die Schreckensrösser existieren auf einer uns fremden Welt, in der feurigen Ebene von Xoroth. Um eines dieser einzigartigen Tiere an Euch zu binden, werdet Ihr mächtige Glyphen beschwören müssen. Ich werde für Euch die erforderlichen Glyphen auf einem Pergament niederschreiben, doch dafür brauche ich eine ganz spezielle Tinte.\n\nIm weit entfernten Winterspring lebt eine besondere Eulenart. Einst waren es normale Tiere, doch die dämonische Macht  der flüsternden Schlucht trieb sie in den Wahnsinn. Übrig blieben nur Blutrünstige Bestien.\n\nEs ist ihr Blut, das ich zum Zeichnen der Glyphen benötige. Bringt mir etwas davon und ich kann Euch weiterhelfen.", sourceObjective = "Mor'zul Bloodbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt.", progress = "Habt Ihr die tobenden Eulenbestien gefunden, {name}? Die Magie dieser Kreaturen ist sehr stark und konzentriert sich besonders im Blut dieser verzerrten Wesen.", completion = "Ausgezeichnet! Ich werde das Blut mit Tinte abmischen und es für die Schriftrolle verwenden, die ich Euch versprochen habe. Vielleicht werde ich ein wenig davon für mich zurückbehalten, denn wie ich hörte, ist der Geschmack des Blutes sehr belebend...", sourceObjectiveStatus = "unverified-source-field" }
quests[7564] = { id = 7564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garzeeki Wildeyes", description = "Mein Assistent Gorzeeki ist ein recht bewanderter Alchimist. Er sollte in der Lage sein die Tinte herzustellen, die ich für die Herstellung der Schriftrolle benötige. Ich habe das von Euch mitgebrachte Blut destilliert. Nehmt es und bringt es zu Gorzeeki, damit er mit seiner Arbeit beginnen kann.", sourceObjective = "Bringt den Behälter mit Blut zu Gorzeeki Wildeyes in der brennenden Steppe.", progress = "Habt Ihr etwas für mich? Ist es zufällig eine große, saftige Spinne? Nicht oder? Oder vielleicht eine Kakerlake? Ich hoffe, sie ist noch am Leben... ich mag es, auf ihnen herumzukauen, wenn sie noch leben...", completion = "Oh, Blut. Bestimmt von Meister Mor'zul. Er liebt das Zeug und mag es, wenn man es literweise vergießt. Ich hingegen bevorzuge es, wenn es noch durch die Venen eines kleinen Nagetiers jagt. Auf die Art bleibt es warm... bis man es braucht.\n\nDieses Blut ist von großer Macht erfüllt. Mor'zul stellt wohl wieder eine Schriftrolle zur Beschwörung eines Schreckensrosses her. Wie aufregend!\n\nFalls das wahr ist und Ihr das Ritual durchführt, dann... werdet Ihr noch einiges mehr als Blut brauchen, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[7581] = { id = 7581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fundament des Gefängnisses", description = "Ihr müsst ein geeignetes Fundament für das Gefängnis der Verdammniswache finden.\n\nDas Blut der Wildhufsatyrn, die in Düsterbruch hausen, sollte dem Genüge tun. Das geronnene Blut wird die Splitter von Hederine zusammenhalten und das Kristallgefängnis mit Energie versorgen.", sourceObjective = "Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der faulenden Narbe zurück.", progress = "Allein das Blut der Wildhufsatyrn wird ausreichend sein.", completion = "Ah, welch' exzellente Ausbeute. Das Blut wird die magische Verteidigung der Verdammniswache  unterdrücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[7582] = { id = 7582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefängnishülle", description = "Die Dämonen von Hederine, die das Vorgebirge des Berges Hyjal bevölkern, sondern mächtige Gifte ab, die mit der Zeit hart und somit zu einem kompakten Anti-Magiekristall werden. Diese Kristalle sind auch als Tränen der Hederine bekannt.\n\nNicht einmal die gewaltige Macht einer Verdammniswache könnte die Wände eines Gefängnisses durchbrechen, die aus diesem Material errichtet wurden.\n\nReist in die flüsternde Schlucht in Winterspring und holt Euch die Tränen.", sourceObjective = "Reist in die flüsternde Schlucht in Winterspring und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt.", progress = "Die Dämonen von Hederine werden Euch ihre wertvollen Steine nicht kampflos überlassen, {name}.", completion = "Ich muss das Blut der Wildhufe lediglich mit diesen Kristallen vereinen, dann sollte das Gefängnis bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[7583] = { id = 7583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterdrückung", description = "Das Gefängnis ist bereit. Jetzt kommen wir zum schwierigsten Teil des Unterfangens.\n\nIhr müsst mit Hilfe des Kristallgefängnisses einen Kommandanten der Verdammniswache in der faulenden Narbe finden und fangen.\n\nSeid gewarnt! Verdammniswachen sind gerissene und tödliche Gegner, die Euch sofort zu zerstören versuchen werden, sobald Ihr mit dem Ritual der Gefangenschaft beginnt. Euer Gegner wird bei seinem Versuch der Gefangenschaft zu entgehen nichts unversucht lassen.\n\nEr wird sich nur auf Euch konzentrieren, {name}. Ich muss Euch deshalb zu der Begleitung von einigen Gefährten raten, die fähig genug sind, um Euch am Leben zu erhalten!", sourceObjective = "Wagt Euch in die faulende Narbe heraus und macht einen Kommandant der Verdammniswache ausfindig.\n\nWendet das leuchtende Kristallgefängnis auf den Kommandanten der Verdammniswache an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.\n\nSolltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der faulenden Narbe.", progress = "Hm? Nun?", completion = "Ihr habt meine Anweisungen befolgt. Das Wissen von der Beschwörung und Kontrolle des Biests kann nun endlich an Euch weitergegeben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[7601] = { id = 7601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibys Anweisungen", description = "Wenn ich Euch das Geheimnis der Beschwörung eines Höllenbestiendieners lehren soll, so müsst Ihr Kroshius zerstören und mir den Höllenbestienkern seiner brennenden Überreste bringen. Wie auch immer, es ist nicht so einfach wie es klingt. Kroshius hat zwar alles, ist aber vollständig ausgebrannt. Ihr müsst seinen Körper wieder entzünden und ihn wieder von dem Schutthaufen auferstehen lassen. Allerdings braucht Ihr dafür ein paar Komponenten von anderen Dämonenwesen.\n\nImpsy, mein Wichtel, soll Euch auf alles weitere vorbereiten.", sourceObjective = "Sprecht mit Impsy im Teufelswald.", completion = "Junge, Junge, jetzt geht's los.", sourceObjectiveStatus = "unverified-source-field" }
quests[7602] = { id = 7602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reine Teufelsessenz", description = "Ihr werdet für die Wiederbelebung von Kroshius Teufelsfeuer benötigen. Ich kann zwar Teufelsfeuer machen, brauche dazu aber ein paar Komponenten.\n\nIhr müsst mir reine Teufelsessenz aus drei bestimmten Gebieten der Welt bringen.\n\nDen ersten Essenztyp findet Ihr bei den Satyrn der Legashi von Azshara; den zweiten Typ bei den Legionären von Jaedenar in Jaedenar und den dritten bei den Wachposten der Teufelswache in den verwüsteten Landen.\n\nBringt mir jeweils eine Essenz pro Typ, dann werde ich das Teufelsfeuer entfachen, mit dem Ihr Kroshius wieder auferstehen lassen könnt.", sourceObjective = "Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\n\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region.\n\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.", progress = "Sagt es keinem, aber Niby ist bescheuert.", completion = "Gebt mir einen Moment, damit ich die drei Essenzen kombinieren und somit das Teufelsfeuer entfachen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[7603] = { id = 7603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroshius Höllenbestienkern", description = "Kroshius liegt zusammengefallen im Shatter Scar-Tal, Richtung Nordosten. Verwendet dieses Teufelsfeuer auf seinen Überresten, es sollte die gefallene Höllenbestie wieder erwecken.\n\nIch bin überzeugt, dass er Euch und Eure eventuell mitgebrachten Begleiter genau dann umbringen wird - und glaubt mir, Ihr werdet ein paar Freunde bei Euch haben wollen.\n\nSolltet Ihr Kroshius dennoch auf wundersame Weise töten können, dann nehmt den Höllenbestienkern und bringt ihn zu Niby.", sourceObjective = "Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\n\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.", progress = "Habt Ihr Euch verlaufen?", completion = "Geschäft ist Geschäft! Schnell, nehmt dies und schreibt dies nieder. Ich habe keine Zeit! Meine größte Beschwörung steht noch bevor!", sourceObjectiveStatus = "unverified-source-field" }
quests[7604] = { id = 7604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbindlicher Vertrag", description = "<Der Unterzeichner/Die Unterzeichnerin> erklärt hiermit, dass es sich bei dem Sulfuronblock, der an die Thoriumbruderschaft (TB Ltd.) geliefert wird, um ein Original und nicht um eine Nachbildung handelt. <Der Unterzeichner/Die Unterzeichnerin> erkennt ebenso an, dass jeglicher Schaden, der <ihm/ihr> in Folge des Versuchs Sulfuras herzustellen, zu schmieden, verkaufen oder zu essen widerfahren könnte, nicht in der Verantwortung oder Verschuldung von TB Ltd. liegt.\n\nMit Unterzeichnung dieses Vetrags, wird allen darin aufgelisteten Bedingungen zugestimmt.\n\n_________________\n\nUnterschrift", sourceObjective = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Darkbargainer, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[7621] = { id = 7621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Warnung", sourceObjective = "{class}, Ihr seid dabei eine entscheidene Reihe von Ereignissen zu durchleben, die alle Eure Fähigkeiten auf die Probe stellen sollen.\n\nIch schlage vor, dass Ihr Euch erst einmal anhört, was ich zu erzählen habe.\n\nLasst Euch gewarnt sein, Ihr müsst diese Aufgabe alleine lösen. Es ist ratsam, dass Eure Verbündeten Abstand halten. Die Einmischung anderer wird eine harte Bestrafung zur Folge haben.\n\nDas Schicksal hat Euch, Euch alleine, hierher geführt. Kämpft mit Ehre. Macht Euch das Licht zu Nutze.", sourceObjectiveStatus = "unverified-source-field" }
quests[7622] = { id = 7622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waage von Licht und Schatten", description = "Ihr müsst tun was ich nicht konnte: Rettet die Arbeiter, die während ihrer Flucht von Stratholme niedergemäht wurden.\n\nSie werden dem Licht entgegen laufen, sorgt für ihr Überleben. Sollten zu viele von ihnen fallen, wird unsere Existenz auch weiterhin verdammt sein - und Ihr werdet versagt haben.\n\nAlle von Euch gelernten Fähigkeiten, Gebete und Zauber werden auf die Probe gestellt werden. Möge das Licht Euch beschützen, {name}.", sourceObjective = "Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Havenfire, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.\n\nKonsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden.", progress = "Werdet Eurem Schicksal gerecht, {name}.", completion = "Eure Hartnäckigkeit und Euer Mut sind verblüffend, {class}. Ihr habt Euch das Recht den Splitter von Nordrassil tragen zu dürfen verdient. Es gilt nur noch eines zu tun: erlangt das Auge der Schatten wieder. Durchstreift die Welt danach.", sourceObjectiveStatus = "unverified-source-field" }
quests[7623] = { id = 7623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Banehollow", description = "Mor'zul sagte mir, dass Ihr ein Portal nach Xoroth öffnen möchtet. Für eine solche Aufgabe werdet Ihr xorothianischen Sternstaub benötigen und der ist nur schwer in Azeroth zu finden!\n\nAber es gibt jemanden, der welchen besitzen sollte: Lord Banehollow in Jaedenar, dem Sitz des Schattenrats! Sprecht mit ihm und vielleicht wird er Euch etwas Sternenstaub überlassen.\n\nDoch wenn Ihr nach Jaedenar wollt, solltet Ihr Euch mit dem gleichen Aroma des Bösen, das den Schattenrat umgibt, tarnen. Dazu werdet Ihr einige meiner schattenhaften Tränke brauchen und die sind nicht umsonst...", sourceObjective = "Erwerbt schattenhaftige Tränke von Gorzeeki in der brennenden Steppe.\n\nBenutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Banehollow.", completion = "Meine Geduld umspannt Jahrtausende, {class}. Aber glaubt nicht das ich Euch mehr als einen kurzen Augenblick meiner Zeit widmen werde...", sourceObjectiveStatus = "unverified-source-field" }
quests[7624] = { id = 7624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulathek der Verräter", description = "Ihr wollt meine Gunst erlangen? Dann tötet für mich.\n\nMein Diener Ulathek treibt ein erbärmliches Spiel, während er wie ein elender Wurm vor mir kriecht, konspiriert er heimlich mit Lord Hel'nurath von Xoroth. Hel'nurath trachtet danach meine Macht an sich zu reißen und Ulathek ist sein Spion...\n\nBeweist mir, dass Ihr mir und nicht meinem Rivalen dient. Stellt Ulathek in seinem Quartier, der Schattenfeste im Osten. Macht ihm klar, dass ich sein kleines Geheimnis kenne und seht wie die Angst von ihm Besitz ergreift. Bringt mir anschließend das Herz des Verräters!", sourceObjective = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Banehollow in Jaedenar.", progress = "Ich schmecke bereits Ulatheks Herz. So süss ist das Herz des Verräters...", completion = "Herrlich! Nach einer Woche des Verfaulens, wird dieses Herz eine saftige Gaumenfreude sein! Vielleicht lasse ich mir noch Ulatheks Kopf bringen und platziere ihn vor mich, während ich esse...\n\nIhr habt mir einen großen Dienst erwiesen, {class} und meine Achtung vor Euch ist gestiegen, wenn auch nur unwesentlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[7625] = { id = 7625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xorothianischer Sternenstaub", description = "Ihr kommt also zu mir, weil Ihr xorothianischen Sternenstaub sucht? Ihr möchtet ein Portal nach Xoroth, dem Herrschaftsgebiet meines Rivalen Hel'nurath öffnen? Vielleicht plant Ihr sogar eines seiner geliebten Schreckensrösser zu stehlen?\n\nNun gut. Mein Diener Ur'dan hat einen Vorrat an Sternenstaub. Ihr könnt es von ihm bekommen... wenn ihr den Preis bezahlen könnt.", sourceObjective = "Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki in der brennenden Steppe.", progress = "Wahrt Ihr schon in Jaedenar, {name}? Habt Ihr den Sternenstaub von Lord Banehollow bekommen?", completion = "Ihr habt ihn! Ich kann kaum glauben, dass Ihr ihn bekommen habt! Wie habt Ihr das geschafft? Seid Ihr einen Handel mit dem Schreckenslord eingegangen oder habt Ihr ihm ein Vermögen für den Sternenstaub angeboten? Vielleicht sogar beides?\n\nMor'zul wird seine Tinte schon bald haben und kann dann die Glyphenschriftrolle herstellen, mit deren Hilfe Ihr ein Portal nach Xoroth öffnen könnt, um eines der gefürchteten Schreckensrösser hindurch zu locken!", sourceObjectiveStatus = "unverified-source-field" }
quests[7626] = { id = 7626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Glocke von Dethmoora", description = "Um einen mächtigen Beschwörungskreis herzustellen, benötigt man eine Glocke von Dethmoora, benannt nach dem uralten Hexenmeister Dethmoora Darkeyes. Richtig abgestimmt mit dem Rad und der Kerze, speichern diese Gegenstände riesige Mengen arkaner Macht.\n\nMein Assistent Gorzeeki kann eine solche Glocke herstellen, allerdings benötigt er dafür einen großen Vorrat an Elixieren der Schattenmacht. Besorgt Euch die Elixiere von einem Alchimisten und bringt sie Gorzeeki.", sourceObjective = "Bringt 10 Elixiere der Schattenmacht zu Gorzeeki Wildeyes in die brennende Steppe.", progress = "Habt Ihr die Elixiere, {name}? Mor'zul sagte mir, dass Ihr eine Glocke von Dethmoora benötigt, doch um sie herzustellen bedarf es vieler Schattenenergien.", completion = "Sehr gut! Ich hoffe, Ihr hattet keine allzu großen Schwierigkeiten bei der Beschaffung der Elixiere. Manchmal sind Alchimisten sehr knauserig, wenn es um ihre Kreationen geht...\n\nIch werde die Glocke jetzt herstellen und sie aufbewahren, bis Ihr für das Ritual bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[7627] = { id = 7627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rad des Schwarzen Marsches", description = "Ein Rad des Schwarzen Marsches enthält und kontrolliert die gefährlichen Energien, welche für das Ritual des mächtigen Beschwörungskreises benötigt werden. Um das Rad zu konstruieren, benötigt Gozeeki große glänzende Splitter von einem Verzauberer und Dunkeleisen von einem Meisterbergmann.\n\nBeschafft diese Gegenstände und bringt sie meinem Assistenten.", sourceObjective = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildeyes in die brennende Steppe.", progress = "Es ist nicht leicht, ein Rad des Schwarzen Marsches herzustellen und es bedarf einer Vielzahl an Materialien. Habt Ihr alles bekommen?", completion = "Wie ich sehe, habt Ihr alles! Ich hörte, dass Dunkeleisenerz nur in den Blackrocktiefen zu finden ist, und ich bin mir sicher, dass es nicht viel einfacher war, an diese Splitter zu gelangen. Die Hingabe, mit der ihr {class} Eurer Tätigkeit nachgeht, beeindruckt mich immer wieder. Ihr solltet Eure Energien lieber in die Kunst des Käferfangens investieren, oh... einen solchen Schmaus würdet Ihr lieben!\n\nEntschuldigt, ich schweife vom Thema ab. Ich werde das Rad jetzt herstellen und es aufbewahren, bis Ihr für das Ritual bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[7628] = { id = 7628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Altarkerze des Jüngsten Gerichts", description = "Eine Altarkerze des Jüngsten Gerichts speichert Feuer in ihrem Inneren und schleudert es auf jeden, der versucht, Euer Ritual zu unterbrechen. Wenn Ihr das Ritual des mächtigen Beschwörungskreises aufbaut und die Kerze angezündet ist, wird sie jeden Dämon der sich Euch in den Weg stellt, mit Ihrer Flamme verbrennen.\n\nDieses spezielle Feuer einzufangen ist nicht einfach und erfordert die Essenz aus der Schuppe eines schwarzen Drachen. Beschafft Euch die Drachenschuppen und bringt sie zu Gorzeeki Wildeyes.", sourceObjective = "Bringt 35 Schuppen eines schwarzen Drachen zu Gorzeeki Wildeyes in der brennenden Steppe.", progress = "Habt Ihr die Drachenschuppen dabei, {name}? Ich möchte die Arbeiten an der Kerze nicht ohne sie beginnen... es könnte sonst passieren, dass ich versehentlich das ganze Lager in die Luft jage.", completion = "Ah, sehr gut. Ich brauche die Schuppen, um das Feuer der Kerze einzufangen. Da ich sie nun habe, kann ich die Kerze jetzt herstellen und aufbewahren, bis Ihr für das Ritual des mächtigen Beschwörungskreises bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[7629] = { id = 7629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtellieferung", description = "Es gibt noch eine Sache die für Mor'zuls Pergament erledigt werden muss. Ich benötige Papier, welches mit xorothianischem Sternenstaub versetzt ist. Leider kann ich diese Prozedur hier nicht durchführen, da mir die Ausrüstung dafür fehlt!\n\nIch kenne aber ein Alchimielabor mit der nötigen Ausstattung. Es befindet sich in der Scholomance, auf der Insel Caer Darrow in den Pestländern.\n\nIch kann diese Reise nicht selber machen, aber nehmt dieses Gefäß. Im Inneren befindet sich ein äußerst intelligenter Wichtel. Lasst ihn frei, wenn Ihr im Alchimielabor angekommen seid und er wird die Prozedur mit dem Sternenstaub für Euch vornehmen.", sourceObjective = "Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildeyes.", progress = "Habt Ihr die Scholomance schon besucht, {name}? Hat der Wichtel das Pergament mit dem Sternenstaub versetzt?", completion = "Herrvorragend! J'eevee konnte das Pergament also herstellen. Wie war Euer kleiner Ausflug nach Scholomance? Nettes Plätzchen, nicht wahr? Und diese leckeren Käfer dort... ich hörte sie sind deliziös!\n\nGut gemacht, {name} und danke, dass Ihr mir mein Gefäß zurückgebracht habt. Ich habe es schon seid einer Ewigkeit... und es ist unverkäuflich!", sourceObjectiveStatus = "unverified-source-field" }
quests[7630] = { id = 7630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanit", description = "Nachdem die Glocke, das Rad und die Kerze jetzt fertiggestellt sind, muss sie jemand auf das Ritual vorbeiten. Ich besitze einen Wichtel, der die Vorbereitungen genau kennt... Ihr braucht nur noch ein Behältnis, um ihn zu transportieren.\n\n Ich kann Euch ein solches Behältnis verkaufen, aber um es herzustellen brauche ich Arkanit. Habt Ihr welches? Falls nicht, solltet Ihr einen Alchimisten finden, der es für Euch herstellen kann.\n\nKommt zu mir zurück, wenn Ihr das Arkanit habt, dann verkaufe ich Euch den Wichtel im Glas!", sourceObjective = "Bringt 3 Arkanitbarren zu Gorzeeki in der brennenden Steppe.", progress = "Habt Ihr das Arkanit, {name}? Sobald Ihr es habt, kann ich Euch ein neues Glas für J'eevee den Wichtel bauen.", completion = "Ihr habt es! Schön gemacht! Jetzt kann ich den Leitstein herstellen. Wenn Ihr schließlich für das Ritual und die Erstellung des mächtigen Beschwörungskreises bereit seid, werdet Ihr einen Leitstein wollen, um ein Fehlschlagen des Rituals verhindern zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[7631] = { id = 7631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensross von Xoroth", description = "Alle Vorbereitungen sind getroffen. Als erstes müsst Ihr das Ritual des mächtigen Beschwörungskreises vollziehen. Anschließend benutzt die xorothianischen Glyphen um ein Portal nach Xoroth zu öffnen.\n\nIch habe Euch die Anweisungen für das Ritual auf eine Schriftrolle geschrieben. Studiert sie sorgfältig, denn wenn Ihr Erfolg haben wollt, müsst Ihr jeden Schritt exakt nach Anleitung durchführen.\n\nIch wünsche Euch viel Erfolg, {name}. Und mögen die Seelen Euerer Feinde, den Weg in Euren Seelensteinbeutel finden.", sourceObjective = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt den Geist des xorothianischen Schreckensrosses bezwungen. Obwohl Ihr den Hass in seinen Augen pulsieren seht, wisst Ihr, dass die Seele der Bestie nun Euch gehört...\n\nLeise flüstert es dunkle Magie in Euren Verstand und Ihr beginnt zu verstehen, wie man ein Schreckensross beschwört.", sourceObjectiveStatus = "unverified-source-field" }
quests[7632] = { id = 7632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das uralte Blatt", description = "Die Epidermis des Blatts leuchtet hellgrün. Die Oberfläche ist extrem runzelig und weist etliche Adern und Falten auf.\n\nMan könnte vermuten, dass dieses Blatt von etwas sehr Altem und Mächtigem stammt.\n\nVielleicht solltet Ihr den ursprünglichen Besitzer dieses Blatts ausfindig machen?", sourceObjective = "Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, {name}; die Welt ist groß.", progress = "<Vartrus stöhnt.>", completion = "Natürlich erkenne ich meine eigenen Blätter wieder. Schaut Euch das hier an! Es ist in perfektem Zustand.\n\nWie gut, dass Ihr es zurückgebracht habt, {class}.\n\nVielleicht könnt Ihr uns ja noch einen Dienst erweisen und wir Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[7633] = { id = 7633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einführung", sourceObjective = "Euer Eifer und Eure Rechtschaffenheit wurden zur Kenntnis genommen, {class}.\n\nWir sind die Uralten, Beschützer dieses einst bedeutenden Waldes. Unsere körperlichen Formen wurden vor 10.000 Jahren zerstört, als Archimonde und die Brennende Legion gegen Hyjal aufmarschierten. Dennoch, unsere Geister blieben unversehrt.\n\nWir haben Aufgaben zu vergeben. Werden diese erfüllt, so werden sie Euch die Geheimnisse der Uralten preisgeben.\n\nWisset, solltet Ihr diese Aufgaben vollenden, so kehrt lediglich zu diesem Felsen zurück und wir werden Euren Ruf erhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[7634] = { id = 7634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes in Sehnen eingewickeltes Laminablatt", description = "Seid gegrüßt, {class}. Ich bin Hastat der Uralte des Wissens. Ich bewahre seit Ewigkeiten verlorenes Wissen.\n\nRichtig gebunden kann eines meiner Blätter als Köcher dienen, dergleichen wurde seit 10.000 Jahren nicht mehr gesehen. Ein Köcher, der - wenn er von einem Bogen der Uralten begleitet wird - ungeahnte Kräfte verleihen könnte.\n\nKehrt mit der Sehne eines ausgewachsenen, blauen Drachens hierher zurück und der Köcher möge Euer sein.", sourceObjective = "Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Hastat im Teufelswald zurück.", progress = "Abermals willkommen, junger {class}.", completion = "Mögen meine Blätter Eure Pfeile vor Schaden schützen. Mögen Eure Pfeile genau treffen. Mögen die Feinde unserer Welt niedergestreckt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[7635] = { id = 7635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die passende Sehne", description = "Vartrus wird Euch womöglich den Holzstab für die Erstellung eines Bogens der Uralten geben. Allerdings kann nur ich die benötigte Sehne verzaubern, die den Bogen vervollständigt.\n\nEs ist eine einfache Aufgabe, mickriges Geschöpf. Tötet einen ausgewachsenen, schwarzen Drachen und entfernt eine Sehne von seinen Knochen. Bringt mir diese Sehne und ich werde das Material in eine fast unzerstörbare Bogensehne verzaubern.", sourceObjective = "Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück.", progress = "Ich bin mir sicher, dass Euch das Auffinden und Töten eines schwarzen Drachens nicht leicht fallen wird, {name}. Verschwendet meine Zeit nicht mit nutzlosem Gerede.", completion = "Das war wohl ein ganz garstiger Drache. Die Sehne stinkt nach Bösen.\n\nGebt mir einen Moment Zeit, damit ich das Fleisch von dem Schmutz säubern  und die passenden Zauber anwenden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[7636] = { id = 7636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holzstab der Uralten", description = "Agenten der Brennenden Legion sind noch immer in unserer Welt aktiv, {class}. Diese Agenten verderben alles, was ihnen unterkommt. Die Natur welkt und siecht in ihrer Gegenwart dahin.\n\nIhr müsst diese dämonischen Verderber aufspüren und zerstören, {name}. Seid gewarnt, Ihr müsst sie selbst angreifen, andernfalls werden sie fliehen. Solange Ihr alleine seid, werden sie versuchen Euch zu zerstören. Ihr müsst sie bekämpfen und ihren Hochmut zu ihrem Verderben werden lassen.\n\nIch gewähre Euch ein Stück meiner Rinde, mögen die Inschriften Euch zu Eurem Ziel führen.", sourceObjective = "Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:\n\nSimone die Verführerin.\n\nKlinfran der Wahnsinnige.\n\nSolenor der Schlächter.\n\nArtorius der Verhängnisvolle.\n\nVernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.\n\nHaltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.\n\nIhr MÜSST diese Aufgabe eigenständig erledigen.", progress = "Lasst Euch nicht von ihren Verkleidungen täuschen!", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}! Nehmt diesen Holzstab und kombiniert ihn mit der Bogensehen, zu deren Fertigung Stoma fähig ist. Zusammen ergibt sich daraus eine vorzügliche Waffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[7637] = { id = 7637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Opfer darbieten", description = "Um Euch auf diese Aufgabe vorzubereiten, müsst Ihr Eure Opferbereitschaft und Euer Urteilsvermögen beweisen... die Betonung liegt hier besonders auf 'opfern'.\n\nIhr benötigt Hohepriester Rohans Weihrauchschwenker für die kommende Aufgabe. Und obwohl Ihr damit gutes bewirken werdet, müsst Ihr etwas zum Ausgleich hergeben.\n\nBegebt Euch nach Ironforge und sprecht dort mit dem Hohepriester. Nehmt reichlich Münzen mit, um ihm den Verlust seines Weihrauchschwenker zu vergelten und um Euren Opferwillen zu zeigen.\n\nGeht nun, {name}, denn Zeit ist hier ein wichtiger Faktor.", sourceObjective = "Reist nach Ironforge und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen.", progress = "Seid gegrüßt, nobler {class}! Ich habe meinen Weihrauchschwenker mit dem allerbesten Weihrauch vorbereitet und ihn für Euch dreifach gesegnet. Eure Spende wird uns hier in Ironforge nicht nur helfen einen neuen Schwenker herzustellen, sondern uns auch dabei helfen, die sinkenden Nahrungsvorräte für unsere Armen wieder aufzufüllen.", completion = "Seid gesegnet, werter {class}. Eure Spende ist weit höher als es nötig gewesen wäre. Euer Opfer kompensiert nicht nur unseren Verlust, es hilft uns auch dabei den Armen und Bedürftigen hier in Ironforge zu helfen.\n\nNun lasst uns sicherstellen, dass ich den Schwenker auch ausreichend für Eure zukünftigen Bedürfnisse vorbereitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[7638] = { id = 7638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Shadowbreaker", description = "{name}, der Zeitpunkt ist nun gekommen, an dem Ihr lernen werdet, was Ihr tun müsst, um etwas zu bekommen, auf das Ihr bestimmt schon lange gewartet habt... Euer eigenes Streitross. Sprecht mit Lord Grayson Shadowbreaker, hier im Kathedralenviertel von Stormwind. Er wird Euch nicht nur in die Geheimnisse des treuesten Begleiters eines Paladins einweihen, sondern er wird Euch auch durch die Prüfungen führen, die Ihr absolvieren werdet, um Euer eigenes Streitross zu erhalten.\n\nIch wünsche Euch viel Glück mit dieser Prüfung. Für das Licht, <nobler Bruder/noble Schwester>!", sourceObjective = "Sprecht mit Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind.", completion = "Ich bin froh Euch zu sehen, {name}. Ich weiß das Ihr lange auf eine Nachricht gewartet habt, wie Ihr an Euer Streitross gelangt und nun ist die Zeit gekommen.\n\nIhr werdet die verschiedensten Prüfungen absolvieren müssen, doch am allermeisten sollt Ihr Euren Willen beweisen, über all den Hindernissen zu stehen, die Euch in Zukunft erwarten werden. Doch diese Prüfungen sind nicht theoretischer oder theologischer Natur. Ihr werdet Euren zukünftigen Begleiter aus den Fängen des Bösen befreien, das Ihr schon so lange bekämpft.\n\n Gebt Acht, Eure Zeit ist nun gekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7639] = { id = 7639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lass Gerechtigkeit walten", description = "Nehmt diesen Weihrauchschwenker mit meinem Segen. Ich selbst habe ihn schon für dutzende Exzorzismen benutzt. Er wird Euch, bei den vor Euch liegenden Aufgaben, gut dienen.\n\nKehrt nun zu Lord Grayson Shadowbreaker in Stormwind zurück. Ihr müsst Eure Suchemit seiner Hilfe fortsetzen.", sourceObjective = "Bringt den Weihrauchschwenker zu Lord Grayson Shadowbreaker in Stormwind zurück.", progress = "Willkommen zurück, {name}. Habt ihr den Weihrauchschwenker erhalten?", completion = "Ja, das wird gehen. Während der vor Euch liegenden Prüfungen werdet Ihr mehr als einmal Eure Opferbereitschaft beweisen müssen. Ich bin froh das Ihr dazu bereit seid. Opferbereitschaft ist eine der grundlegensten Eigenschaften die man besitzen muss, um den Pflichten eines Paladins nachkommen zu können... ich denke, was das betrifft, muss ich Euch keine Lektion mehr erteilen. Am Ende, ist dieser Weihrauchschwenker das Werkzeug, mit dem Ihr Gerechtigkeit walten lassen werdet, unter all den gequälten Seelen, in den für uns verlorenen Ländereien.", sourceObjectiveStatus = "unverified-source-field" }
quests[7640] = { id = 7640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exorzismus des Schreckenstals", description = "Ich habe ein wenig von der verdorbenen Erde des Schreckenstals, aus den östlichen Pestländern, in den Weihrauchschwenker getan. Benutzt den Schwenker, um Gebiete die von spiritueller Unruhe und Störungen befallen sind, ausfindig zu machen. Haltet nach grünen Auren Ausschau, die die Erde durchziehen, während sich die materielle Welt unter den Qualen der Spirituellen Ebene verzerrt. Benutzt dort den Weihrauchschwenker, um die Geister des Bösen zu vertreiben.\n\nHabt Ihr erst einmal genug Gerechtigkeit unter den Geistern walten lassen, seid Ihr bereit für Euren weiteren Weg.", sourceObjective = "Vertreibt mit Hilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind zurück.", progress = "Es ist schön Euch wiederzusehen, {name}. Habt Ihr Eure Aufgabe im Schreckenstal abgeschlossen?", completion = "Gut gemacht, {name}. Denen, die in der Dunkelheit leben, die Gerechtigkeit des Lichts zu bringen, ist eine Aufgabe der wir uns mit Leib uns Seele verschrieben haben. Durch Euer Opfer in Ironforge und durch das Richten der Geister im Schreckenstal, habt Ihr genau dies getan.\n\nDer nächste Schritt erfordert sowohl Aufopferung, als auch das Wirken von Gerechtigkeit. Ihr werdet losziehen um den Geist eines gefallenen Streitrosses zu erlösen, welches nun dem Todesritter Schattensichel dient.", sourceObjectiveStatus = "unverified-source-field" }
quests[7641] = { id = 7641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimand Elmores Werk", description = "Ohne ein angemessenes Pferdegeschirr,  ist das Streitross eines Paladins nichts weiter als ein Packesel. Das Pferdegeschirr für Euer Streitross sollte aus den bestmöglichem Material gefertigt sein und in Eurem speziellen Fall muss es auch noch mit der spirituellen Ebene abgestimmt werden.\n\nAber zuerst einmal muss Euer Pferdegeschirr gefertigt werden. Im Zwergendistrikt lebt einer der besten Schmiede unserer Zeit, Grimand Elmore. Seine Arbeit wird zwar nicht gerade billig sein, aber seine Qualität ist genau das, was wir suchen. Sprecht mit Ihm.", sourceObjective = "Sprecht mit Grimand Elmore im Zwergendistrikt von Stormwind.", completion = "Hallo da, Kumpel - Lord Shadowbreaker hat mich von Eurer Ankuft informiert und das Ihr mich sehen wollt. Ich werde Euch das Pferdegeschirr anfertigen. Aber um eines klarzustellen, es wird weder einfach noch billig sein.\n\nIch werde nur das eine sagen, und Grayson wird mir zustimmen... Nirgendwo in ganz Azeroth werdet Ihr ein besseres Pferdegeschirr finden, als hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[7642] = { id = 7642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fünf Dinge", description = "Ich benötige vier Dinge für das Pferdegeschirr - Runenstoff für das Innenfutter, Arkanitbarren für die Panzerung, Arthas' Tränen für den spirituellen Einklang und heiliges Wasser aus Stratholme zur spirituellen Stärkung. Nun, genau genommen braucht Ihr noch eine fünfte Sache... Gold um mich zu bezahlen. Die Bezahlung umfasst alle anfallenden Arbeiten, sowie einen handgemachten Sattel und Steigbügel.\n\nWenn Ihr alles gebracht habt, kann ich Euer Pferdegeschirr fertigstellen. Bis Ihr alle Sachen beisammen habt, werde ich schon einmal einige der Arbeiten für Euch erledigen können.", sourceObjective = "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Artha's Tränen, 5 Phiolen heiliges Wasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Stormwind.", progress = "Ah, {name}. Ich kann Euer Pferdegeschirr erst fertigstellen, wenn Ihr mir die Sachen bringt um die ich Euch gebeten habe. Habt Ihr alles beisammen?", completion = "Das... nun, es ist alles was ich brauche. Ihr seid ein ganz schön einfallsreicher {class}, oder?\n\nOk, dann machen wir mal Euer Pferdegeschirr fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[7643] = { id = 7643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der uralte Pferdegeist", description = "Euer Pferdegeschirr braucht eine ganz spezielle Form von Segnung, durch einem geeigneten Geist. In Düsterbruch findet Ihr einen solchen Geist, der uralte Pferdegeist. Er ist im Besitz eines verdorbenen Treants namens Tendris Wucherborke. Richtet dieses verdorbene Biest, {name}. Doch wisset eines - Freiheit ist nicht alles. Ihr müsst den Geist erst beschwichtigen, wenn Ihr seinen Segen wollt. Dafür werdet Ihr ein spezielles Pferdefutter benötigen. Reist zuerst nach Southshore und sprecht mit Merideth Carlson über diese Sache... und bereitet Euch auf weitere Opfer vor.", sourceObjective = "Beschafft spezielles Pferdefutter mit dem man ein Geisterpferd füttern kann. Meredith Carlson in Southshore scheint dafür eine recht gute Quelle zu sein.\n\nReist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen.", progress = "Der uralte Pferdegeist sieht Euch erwartungsvoll an, es scheint als wollte er etwas von Euch.", completion = "Der uralte Pferdegeist akzeptiert das von Euch angebotene mit Mana angereichertes Pferdefutter. Nachdem es etwas von dem Futter gegessen hat, scheint es auf Euer Pferdegeschirr zu blicken, als wolle es, dass Ihr es ihm anlegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7644] = { id = 7644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Arkanitpferdegeschirr", description = "Als Ihr dem uralten Pferdegeist das Pferdegeschirr anlegt, beginnt dieses langsam zu leuchten. Die Luft ist erfüllt von diesem heiligen Moment. Urplötzlich verschwindet das Pferdegeschirr und  erscheint wieder in Eurem Rucksack.\n\nEs scheint so, als wäre das Pferdegeschirr wahrhaftig gesegnet. Entsprechend Lord Shadowbreakers Anweisungen müsst Ihr nun mit ihm nach Stormwind zurückkehren.", sourceObjective = "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Shadowbreaker in das Kathedralenviertel von Stormwind zurück.", progress = "{name}, Ihr seid zurück! Seid Ihr mit Meridith Carlson und Tendris Wucherborke zurechtgekommen? Ehrlich gesagt weiß ich nicht, wer von den beiden die größere Gefahr darstellt.", completion = "Ihr seid weit gekommen, mein Freund. Das Pferdegeschirr ist nun bereit für die letzte Aufgabe.\n\nSattelt das Streitross mit dem Pferdegeschirr, nachdem Ihr die Aufgabe der Erlösen abgeschlossen habt. Doch zuvor habt Ihr noch einen großen Kampf zu bestehen. Eure Zeit ist gekommen - Huzzah!\n\nEs muss noch ein letzter Gegenstand gefertigt werden, bevor wir anfangen können, {name}. Hoffentlich verfügt Ihr noch über soviele Mittel wie damals, als ich Euer Pferdegeschirr gefertigt habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[7645] = { id = 7645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Mana angereichertes Pferdefutter", description = "Die Silberhand hielt mich für VERRÜCKT, als ich erzählte, dass ich spezielles Pferdefutter für spirituelle Pferde herstellen könnte. ALLE dachten ich sei verrückt! Nun, der Tag meiner Revanche ist gekommen!\n\nIch werde herstellen, was Ihr braucht, PALADIN... sogenannter HELD... allerdings wird es Euch einiges kosten. Ich brauche für diese Mischung spezielle Kekse - angereicherte Manakekse, die nur von der Argentumdämmerung verkauft werden. Außerdem fordere ich - ja, ich FORDERE - Gold als Entschädigung für mein erlittenes Elend!\n\nBringt mir die Opfer, zu dessen Erbringung Ihr so ausdrücklich bereit gewesen seid, PALADIN.", sourceObjective = "Treibt 20 angereicherte Manakekse - die ausschlaggebende Zutat für die Herstellung von mit Mana angereichertem Pferdefutter - für Merideth Carlson aus Southshore in dem Vorgebirge von Hillsbrad auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt.\n\nZusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen.", progress = "Habe ich Euch jetzt vom Gegenteil überzeugt, ja? Sie hatten alle Unrecht! ICH WAR SCHON DIE GANZE ZEIT IM RECHT!!!", completion = "JA, JETZT... wartet... Ihr gebt mir auch das Gold? Zwar wart es nicht Ihr, die mich eine Verrückte nannten… oder genauer gesagt eine komplett durchgeknallte Spinnerin… dennoch bin ich erstaunt, dass Ihr dazu bereit seid, Opfer für Fehler aufzubringen, an denen Ihr selbst keine Schuld tragt.?\n\nIch... ich habe Euch falsch eingeschätzt. Solltet Ihr noch mehr Pferdefutter benötigen, so kommt zu mir. Ich werde es Euch umsonst geben. Danke... großmütiger {class}.\n\nIch werde das Geld trotzdem behalten - ich bin nicht so verblödet, als dass ich ein Vermögen aufgeben würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[7646] = { id = 7646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Orakel der Anrufung", description = "Als nächstes müssen wir ein Orakel der Anrufung erschaffen - Damit wird Eure Prüfung beginnen, an dessen Ende Ihr das gefallende Streitross erlösen werdet. Euer Orakel ist schon beinahe vollständig. Der von Euch im Schreckenstal eingesetzte Weihrauchschwenker wird als Katalysator für das Orakel dienen und ich werde Euch ein passendes Gehäuse für das Gerät anfertigen.\n\nDie letzen noch benötigten Komponenten, sind zwei Diamanten. Sie müssen von reinster Qualität sein und gleichermaßen gut ihren Zweck erfüllen - ein azerotischer und ein schwarzer Diamant. Zusammen werden diese beiden das Leuchtfeuer sein, mit dessen Hilfe das Orakel die Schatten zerschneiden wird.", sourceObjective = "Bringt Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind einen Azerothianischen Diamanten und einen makellosen schwarzen Diamanten.", progress = "Ihr seid schon sehr weit gekommen, {name}. Der letze Akt einer weltlichen Opferung, wird der Beginn eines Euerer größten Leistungen sein. Ich kann es im innersten meiner Seele spüren!", completion = "Dies sind fantastische Exemplare, {name} - Die letzten Teile habe ich angebracht. Zu guter Letzt, ist Eure Zeit gekommen!\n\n In den Tiefen des großen Ossuariums von Scholomance liegen die Überreste vieler Wesen. Unter ihnen befindet sich ein einst nobles Streitross. Die gequälte Seele dieses Streitrosses dient nun dem Todesritter Schattensichel. Ihm werdet Ihr Euch stellen müssen, und es ist sein Ross dem Ihr Gerechtigkeit wiederfahren lassen werdet. Nur Ihr, {name} könnt diese Seele erlösen und es aus den Qualen seiner Knechtschaft befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[7647] = { id = 7647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit und Erlösung", description = "Nehmt diese Tasche - in ihr befinden sich alle Gegenstände, die Ihr für Eure Aufgabe brauchen werdet.\n\nBenutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, um die verfluchten Geister zu rufen, über deren Schicksal gerichtet werden muss. Benutzt Eure Richturteile während dieser Prüfung weise - Sie werden weit wirksamer sein, als Ihr es Euch vorstellen könnt. Nach diesen Geistern wird der Todesritter erscheinen. Besiegt ihn und fordert die verlorene Seele des Streitrosses. Nur dann werdet Ihr in der Lage sein, es zu erlösen und Eurem neuen Reittier Euer Zaumzeug anlegen können!\n\nViel Glück!", sourceObjective = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses.\n\nGebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück.", progress = "Der Geist des gefallenen Streitrosses blickt Euch voller Trauer an. Traurige, ja fast leere Augen blicken Euch an, als sei jede Hoffnung verloren.", completion = "Ein Lebensfunke erstrahlt in den Augen des armen Tieres als Ihr ihm seine verlorene Seele zurückgebt. Ihr fühlt die plötzliche Präsenz heiliger Energien um Euch und legt Ihm das Pferdegeschirr an. Das Streitross schnüffelt neugierig an Eurer Hand und die Bürden der Vergangenheit scheinen von ihm gewichen zu sein. Ihr fühlt, dass Ihr dieses Pferd jederzeit herbeirufen könnt, solltet Ihr seine Hilfe brauchen.\n\nIhr habt Euer episches Streitross erhalten, {class}. Gratulation!", sourceObjectiveStatus = "unverified-source-field" }
quests[7648] = { id = 7648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimands feinste Arbeit", description = "<Grimand wischt sich Schweiß von seinen Brauen und strahlt stolz.>\n\nDa wären wir, <mein Freund/meine Freundin>. Dies ist eine meiner besten Arbeiten  - so gut wie das Pferdegeschirr, das ich persönlich für Lord Shadowbreaker gefertigt habe, als dieser sich für sein eigenes Streitross aufmachte. Ich danke Euch für Euer Vertrauen in mein Können.\n\nGrayson wird diese Arbeit zweifellos auch sehen wollen. Bringt Euer Pferdegeschirr zu ihm und richtet ihm meinen Dank für die ehrenvollen Geschäfte mit ihm aus.", sourceObjective = "Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind.", progress = "Ihr kommt gut voran, {name}. Sobald Euer Pferdegeschirr fertiggestellt ist, werdet Ihr die nächste Aufgabe angehen können.", completion = "Das ist die beeindruckendste Arbeit, die ich je gesehen habe. Es scheint, dass Grimands handwerkliches Können mit dem Alter immer besser wird. Es ist eine beachtliche Leistung, wenn man bedenkt, dass seine Arbeiten bereits zu den besten zählten, als er damals mein Pferdegeschirr anfertigte.\n\nObwohl dieses Geschirr auch eine schöne Bereicherung für jedes normale Pferd darstellen würde, geben wir uns nicht mit derartig alltäglichen Geschöpfen ab. Ihr müsst dieses Geschirr auf entsprechende Weise segnen lassen, auf dass es würdig genug ist, um einem {class}-Streitross angelegt zu werden. Bis dahin werde ich es für Euch aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[7649] = { id = 7649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberter Thoriumplattenpanzer: Band I", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n< Lydros reißt eine Seite aus dem Buch> \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept.", sourceObjectiveStatus = "unverified-source-field" }
quests[7650] = { id = 7650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberter Thoriumplattenpanzer: Band II", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n< Lydros reißt eine Seite aus dem Buch> \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept.", sourceObjectiveStatus = "unverified-source-field" }
quests[7651] = { id = 7651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberter Thoriumplattenpanzer: Band III", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, mein Sohn.\n\n< Lydros reißt eine Seite aus dem Buch> \n\nIch bin sicher Ihr habt eine Verwendung für dieses Rezept.", sourceObjectiveStatus = "unverified-source-field" }
quests[7652] = { id = 7652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sonderangebot", sourceObjective = "Okay, Junge, ich habe da ein heißes Angebot für dich.\n\n Ich habe hier einige Pläne zur Herstellung von imperialen Plattenrüstungen, die ich gerne loswerden möchte. Das einzige, was ich als Gegenleistung verlange, sind einige Thoriumbarren. Klingt doch gut, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[7653] = { id = 7653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperialer Plattengürtel", progress = "Das macht 20 Thoriumbarren für die Pläne des Plattengürtels, Junge.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7654] = { id = 7654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenstiefel", progress = "Thoriumbarren, Junge. Genau 40! Heulst du gleich? Soll ich dich in den Arm nehmen?\n\n<Malyfous lacht lauthals.>", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7655] = { id = 7655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenarmschienen", progress = "Du willst die Pläne für die Armschienen? Das ganze kostet dich nur 20 Thoriumbarren.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7656] = { id = 7656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", progress = "Junge, für die Pläne der Plattenrüstung krieg' ich 60 Thoriumbarren. \n\nJetzt geht das wieder los. Gleich rennst du wohl wieder zu deinen ach so mächtigen Göttern und jammerst! Stell dich nicht so an, Weichei! Niemand hat behauptet, dass das Leben fair wäre!", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7657] = { id = 7657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperialer Plattenhelm", progress = "Gib mir einfach 50 Thoriumbarren und die Pläne für den Helm gehören dir.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7658] = { id = 7658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattengamaschen", progress = "Reich mir einfach 60 Thoriumbarren 'rüber und die Pläne für die Gamaschen gehören dir. \n\n Ja, ja ich bin dein Ruin. Diese Geschichten muss ich mir jedes mal anhören. Also spar dir den Mist, Weichei.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7659] = { id = 7659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenschultern", progress = "Du willst die Pläne für die Plattenschultern? Das macht 20 Thoriumbarren.", completion = "Es war mir eine Freude mit dir Geschäfte zu machen!\n\n Und {name}... spar' dir diesen abfälligen Blick!" }
quests[7660] = { id = 7660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfstausch - arktischer Wolf" }
