quests[7665] = { id = 7665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austausch Eures roten Raptors" }
quests[7666] = { id = 7666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneut im großen Ossuarium", sourceObjective = "Wart Ihr schon zurück in Scholomance, {name}? Ihr habt bereits teuer für die Verwendung des Orakels der Anrufung bezahlt - vielleicht möchtet Ihr ja noch ein weiteres mit Euch nehmen. Ihr wäret damit in der Lage, Euch den Gefahren des großen Ossuariums erneut zu stellen.\n\nFür alle Fälle, hier habt Ihr es. Ihr habt es Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[7667] = { id = 7667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materielle Unterstützung", description = "{name}, es gibt da eine dringliche Angelegenheit und ich hoffe, dass Ihr mir dabei helfen könnt... im materiellen und geistigen Sinne. Lasst mich bitte erklären.\n\nTief in Scholomance in Lordaeron gibt es ein Gewölbe, das das große Ossuarium genannt wird. Ich muss eine Vorrichtung fertigstellen, die die Schatten dieses entsetzlichen Raums durchbohren kann. Um zu beenden, womit ich begonnen habe, brauche ich zwei Diamanten: einen azerothianischen und einen makellosen schwarzen Diamanten. Dies sind keine gewöhnlichen Objekte, ich weiß - aber ich verfüge nun einmal nicht selbst über die entsprechenden Mittel.\n\nKönntet Ihr mir jeweils einen von beiden beschaffen?", sourceObjective = "Wenn Ihr Sagorne Crestrider im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothianischen und einen makellosen schwarzen Diamanten.", progress = "Es ist mir unangenehm, um materielle Unterstützung zu bitten, aber mein Orakel der Anrufung - die Vorrichtung, die ich fertigzustellen hoffe - benötigt jeweils einen von beiden. Wenn Ihr mir nicht helfen könnt, kann ich das natürlich verstehen.", completion = "Eure Großzügigkeit ist unbeschreiblich, {name}. Ich danke Euch für Eure Güte.\n\nIch kann mein Orakel der Anrufung nun vollenden und sollte jetzt auch ohne weitere Diamanten mehr davon herstellen können... vielleicht interessiert es Euch ja, mir bei dessen Anwendung behilflich zu sein? Ich versichere Euch, es handelt sich dabei um eine wirklich wichtige Aufgabe... eine, die wenn sie unerledigt bleibt, auf der spirituellen Ebene eine riesige Katastrophe verursachen könnte!", sourceObjectiveStatus = "unverified-source-field" }
quests[7668] = { id = 7668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung durch Schattensichel", description = "Der Todesritter Schattensichel herrscht über das große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen... Er muss gestoppt werden! Dabei kommt das Orakel der Anrufung, bei dessen Herstellung Ihr behilflich wart, zum Einsatz.\n\nSetzt das Orakel inmitten des Kellergewölbes des großen Ossuariums ein, um Schattensichels Geistergefolge herbeizurufen. Besiegt die Geister und der Todesritter selbst wird erscheinen. {name}, bringt mir seinen Kopf! Lediglich seine Niederlage wird den Schaden, den er der spirituellen Ebene zugefügt hat, wieder umkehren können!", sourceObjective = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Creststrider im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[7669] = { id = 7669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneut im großen Ossuarium", sourceObjective = "Wart Ihr schon zurück in Scholomance, {name}? Ihr habt bereits teuer für die Verwendung des Orakels der Anrufung bezahlt - vielleicht möchtet Ihr ja noch ein weiteres mit Euch nehmen. Ihr wäret damit in der Lage, Euch den Gefahren des großen Ossuariums erneut zu stellen.\n\nFür alle Fälle, hier habt Ihr es. Ihr habt es Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[7670] = { id = 7670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Shadowbreaker", description = "{name}, der Zeitpunkt ist nun gekommen, an dem Ihr lernen werdet, was Ihr tun müsst, um etwas zu bekommen, auf das Ihr bestimmt schon lange gewartet habt... Euer eigenes Streitross. Sprecht mit Lord Grayson Shadowbreaker, im Kathedralenviertel von Stormwind. Er wird Euch nicht nur in die Geheimnisse des treuesten Begleiters eines Paladins einweihen, sondern er wird Euch auch durch die Prüfungen führen, die Ihr absolvieren werdet, um Euer eigenes Streitross zu erhalten.\n\nIch wünsche Euch viel Glück mit dieser Prüfung. Für das Licht, <nobler Bruder/noble Schwester>!", sourceObjective = "Sprecht mit Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind.", completion = "Ich bin froh Euch zu sehen, {name}. Ich weiß das Ihr lange auf eine Nachricht gewartet habt, wie Ihr an Euer Streitross gelangt und nun ist die Zeit gekommen.\n\nIhr werdet die verschiedensten Prüfungen absolvieren müssen, doch am allermeisten sollt Ihr Euren Willen beweisen, über all den Hindernissen zu stehen, die Euch in Zukunft erwarten werden. Doch diese Prüfungen sind nicht theoretischer oder theologischer Natur. Ihr werdet Euren zukünftigen Begleiter aus den Fängen des Bösen befreien, das Ihr schon so lange bekämpft.\n\n Gebt Acht, Eure Zeit ist nun gekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7671] = { id = 7671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatz für Euren Frostsäbler" }
