quests[7677] = { id = 7677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austausch Eures Schimmels" }
quests[7678] = { id = 7678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austausch Eures Palominos" }
quests[7701] = { id = 7701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorarbeiter Maltorius", description = "Auf Anordnung seiner Eminenz, Aufseher Oilfist, des Agenten der Thoriumbruderschaft und gleichzeitig neu angeheuerten Kommandanten der Schlackengrubentruppe der Dunkeleisenzwerge des Kessels, soll Aufseher Maltorius getötet und sein Kopf als Beweis für die Tat erbracht werden. \n\nTrefft Euch mit dem Captain des Ausgucks, Lolo Longstriker, wegen der Belohnung für diese schwierige Aufgabe.", sourceObjective = "Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden. \n\nTötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Ausguck Captain Lolo Longstriker in der sengenden Schlucht für eine Belohnung.", progress = "Siieschte niichh dass isch beschäftischt bin?! Was *hicks* wollllt ihr denn *hicks*?", completion = "Isch hätt' nie gedacht, dasch ich diiieschem Ganoven nochmal in die Augen schauen würde!\n\nOhne den Rescht voo' ihm sieht er doch viiel bescha aus, findet Ihr nisch?\n\nHier's Eure Belohnung *hicks*, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[7702] = { id = 7702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie mit Schlafentzug", description = "Wenn wir die Produktivität der Dunkeleisenzwerge in der Schlackengrube behindern wollen, müssen wir sie dort treffen wo es am meisten schmerzt. .\n\nEs ist eine wenig bekannte Tatsache, aber Zwerge müssen sich ausruhen, besonders die Dunkeleisenzwerge! Die brauchen viel Ruhe!\n\nNun frage ich Euch, wie können sie ohne Kissen schlafen? Genau, {name}, sie können es nicht. Das ist der Grund, aus dem Ihr euch in die Schlackengrube begeben müsst, um ihre Kissen zu stehlen.", sourceObjective = "Tief in der Schlackengrube des Kessels, findet Ihr die Schlafräume der Dunkeleisenzwerge.\n\nFindet diese Schlafkammern und stibitzt 20 Dunkeleisenkissen. Kehrt dann zu Evonice Rußraucher in der Sengenden Schlucht, wenn Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7703] = { id = 7703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elfen, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de' wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", sourceObjective = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.\n\nKromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", progress = "Hah, Ihr nicht gefunden, oder Chef?  Vielleicht alte Zeit Geschichte, schlechte Geschichte... schwer zu glauben das schrecklicher Elf von Gordokkönig stehlen kann!", completion = "Wow... Ihr SEID de' wahre König! Ich nie gedacht, dass ich je wiedersehen diese Stulpen in meinem Leben!  Es aussehen als ob sie kein Mojo mehr haben... vielleicht de' gruselige Elf hat sich an Stulpen versucht und sie kaputt gemacht.\n\n Guckt - dieses Zeichen auf de' Stulpen ist ein sehr sehr sehr altes Zeit Symbol. Älter als Gordok, sagen sie. Nun, als Captain von de' Gordok, bekommen eines immer und immer wieder beigebracht - wie man machen Zeichen wieder lebendig, um geben den Stulpen die Kraft zurück!\n\nIch werde es für Euch tun, König! Hier, nehmen Stulpen und herrschen AUF EWIG!", sourceObjectiveStatus = "unverified-source-field" }
quests[7704] = { id = 7704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schau dir die Größe an!", description = "Ja, ja… wenn das nicht eine Überraschung ist. Das Zimmermädchen besaß ein riesiges verziertes Kissen und nun ist es Eures. Geht zu Evonice Sootsmoker, sie kann es nicht erwarten dieses Kissen zu bekommen und mit ihren fettigen Händen zu begrapschen. Bringt es ihr und schaut ob sie Euch dafür auch irgendwie für die Mühen entlohnt.", sourceObjective = "Bringt das Kissen von Zimmermädchen Kissenquetscher zu Evonice Sootsmoker in der sengenden Schlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[7721] = { id = 7721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoff fürs Schrumpfen", description = "Wenn ich gegen meinen besseres Wissen und Gewissen handele und nun doch bleibe, um meinen Ingenieurladen an der Vergessenen Küste aufzumachen, muss ich mich dringend um diese nervigen Elementare kümmern. Verdammt sei der unkontrollierte Elementalismus, sage ich!\n\nGlücklicherweise stellen die Elementare eine ideale Quelle reiner Kraft für meinen Super-Schrumpfer dar – insofern, gebt ihnen Saures! Wenn Ihr dies allerdings tut, seid sicher, dass Ihr mir auch ein paar Elementarkerne sammelt.", sourceObjective = "Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks.", progress = "Ich könnte Euch zwar mit den technischen Details über den Nutzen der Elementarkerne langweilen, aber ich werde Euch lieber mit ein paar Münzen und anderen Belohnungen in Versuchung führen, damit ihr diese wichtige Aufgabe abschließt. So ist es die Wahrheit, seid Ihr wirklich fertig?", completion = "Hervorragend! Diese Kerne werden mich einige Zeit beschäftigen. Nicht zu vergessen, die Tatsache, dass es entlang der Küste nun weniger Elementare gibt, die uns Sorgen bereiten müssten. Möglicherweise muss ich mich jetzt nicht mehr in den Schlaf weinen, wenn ich daran denke, dass ich mein Lager ausgerechnet am schlimmsten Ort der Welt aufgeschlagen habe.\n\nVielen Dank {name}, für Eure Hilfe in dieser Angelegenheit. Es mag vielleicht meine Finanzen ein wenig überstrapazieren, aber ich denke ich möchte mein Wohlwollen Euch gegenüber in einer Weise ausdrücken, die Ihr versteht... ich hätte da einige Ausrüstung für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[7722] = { id = 7722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Fluxus?!", description = "Als dieser Bastard Maltorius unseren Klan verließ, verließ er ihn mit etwas viel wertvollerem als einem makellosen Arkankristall: Unserem Rezept für den feurigen Fluxus! Ich verwette mein letztes Hemd, dass das ein Teil der Absprache für seine Beförderung innerhalb der Dunkeleisenzwerge war.\n\nBringt unsere geheimen Pläne zurück, {name}. Ich bin mir sicher, dass sie in der Nähe von Maltorius, tief in der Schlackengrube sind.", sourceObjective = "Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht.", progress = "Habt Ihr die Pläne gefunden?", completion = "Hoffentlich habt Ihr dem Kerl ordentlich in den Hintern getreten, {name}. Ragnaros weiß das er es verdient hat.\n\nAber jetzt zurück zum Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[7723] = { id = 7723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt seien diese fetten Finger", description = "Unglücklicherweise kann ich nicht mehr so austeilen, wie es früher einmal konnte, dank meines Problems hier, meine fetten Finger. Das Klima hier draußen und dazu der geringe Luftdruck lässt meine Finger einfach aufquellen. Die sehen schon aus wie gigantische Thelsamarer Blutwürste...\n\nDu wirst meine Aufträge ausführen müssen. \n\nAls erstes steht auf meiner Liste: Prügelt das letzte bisschen Leben aus den Schweren Kriegsgolems in der Schlucht. Leg los!", sourceObjective = "Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet. \n\nDie Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", completion = "Ihr seid gar nicht mal so übel. Ich hab' Euch nen' kleines Geschenk besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7724] = { id = 7724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feurige Bedrohung!", description = "Würd' ich's nicht besser wissen, würd' ich behaupten, dass jedesmal, wenn der alte Hansel sich endlich 'mal ein wenig entspannen möchte, ihm die höheren Mächte einen weiteren Auftrag erteilen.\n\nDas macht mich echt nachdenklich, weißt du? Du weißt doch was ich meine, oder?\n\nDie Lavaspinnen hier in der Gegend, haben in der letzten Zeit einen ganz schönen Krawall verursacht. Oilfist meint, dass sie aus ihren Hinterteilen Feuer spucken würden und das so etwas die Kinder beunruhigt.\n\nSchätze wir werden sie erledigen müssen. Genau genommen wird das dein Job sein.", sourceObjective = "Hansel Heavyhands möchte, dass Ihr 20 große Lavaspinnen in der sengenden Schlucht tötet. \n\nDie großen Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der segenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", completion = "<Hansel niest.>\n\nMist, ich glaub' ich krieg' eine Erkältung. Dieses verdammte kalte Klima hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[7725] = { id = 7725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und wieder unter den geschrumpften Riesen", description = "Ich weiß, dass Ihr schon Überreste für mich gesammelt habt... aber solltet ihr auf der Suche nach einer zusätzlichen Aufgabe sein, könnte ich immer noch einige Überreste gebrauchen.\n\nIch kann zwar nicht genausoviel als Belohnung bieten wie zuvor, aber dafür wäre ich mehr als glücklich ein gutes Wort über Euch unter meinen Goblin Freunden verlauten zu lassen. Unter denen zumindest, die über Ohren verfügen. .\n\nGlaubt mir, <Herr/Frau> wenn ich Euch sage, dass diese Goblins über wirklich ziemliche große Ohren verfügen.", sourceObjective = "Benutzt Zorbins Super-Schrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt 10 Schrumpf-Überreste, die auf den kleineren handlicheren Riesen liegen zu Zorbin Fandazzle am Dock der Vergessenen Küste in Feralas.", progress = "Ah, die Früchte langer Arbeit und Forschung: süsse süsse Überreste. Natürlich probiere ich während meiner Studien nichts davon...\n\nMeistens jedenfalls.", completion = "Einfach fantastisch, {name}! Wieder einmal habt Ihr mir einen großen Gefallen getan und dafür danke ich Euch.\n\nVielen Dank!\n\nDiese Belohnung mag vielleicht ein wenig kleiner ausgefallen sein, als Ihr es vielleicht gewohnt seid, aber seid Euch sicher, dass Eure großen Taten im Namen der Goblins, überall in den großen Hallen des Steamwheedle-Kartells wiederhallen. Solltet Ihr mal wieder Arbeit suchen, dann um der Götter Willen, redet mit mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[7726] = { id = 7726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Treibstoff fürs Schrumpfen", description = "Mehr Arbeit, sagt Ihr? Hat meine heroische Aufgabe des Schleimsammelns von den Elementaren nicht Euren Durst nach Abenteuern gelöscht? Vielleicht wird etwas mehr davon den unerschöpflichen Brunnen der Ihr seid füllen...\n\nok, Melodramatik beiseite, Ich bräuchte noch ein paar Wasserelementarkerne. Ich versuche verzweifelt einen Laden hier aufzumachen, also wird der Lohn leider nicht groß sein... aber ich verspreche, dass ich jedem in Hörweite erzählen werde, dass Ihr mir geholfen habt. Vertraut mir – Ich kenne eine Menge Leute im Kartell!", sourceObjective = "Sammelt 6 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks.", progress = "Habt Ihr die Elementarkerne bekommen, um die ich Euch gebeten habe?", completion = "Erstklassik, {name}, erstklassik! Diese Belohnung mag vielleicht nicht die wertvollste sein, die Ihr je erhalten habt. Stattdessen seid Euch sicher, dass meine Kameraden im Steamwheedle-Kartell von Euren Bemühungen erfahren werden!\n\nLasst es mich wissen, wenn Ihr mal wieder nach Arbeit sucht. Ich kann immer einige weitere Elementarkerne gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7727] = { id = 7727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendosaurier? Was-auch-immer-Saurier?", description = "Meine Zehen, <Kumpel/Mädel>. Meine verdammten Zehen sind angeschwollen. Wie soll ich irgendetwas jagen können, wenn meine Füße mich schon umbringen? Darum brauche ich Eure Hilfe.\n\nScrange und Burninate haben mich beauftragt, diese \"Dinger\" zur Strecke zu bringen, damit sie weitere Expeditionen in die Lavabecken der Schlackengrube schicken können. Anscheinend stehen einige Incendosaurier oder sowas in der Art diesem Vorhaben im Weg... Wollt Ihr hier Wurzeln schlagen oder habt Ihr die Incendosaurier schon erledigt?", sourceObjective = "Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet.\n\nDie Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der segenden Schlucht.\n\nSobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Heavyhands in der sengenden Schlucht zurück.", completion = "Oh, meine schmerzenden Füße bringen mich nochmal um.\n\nUnd Ihr habt ganz sicher keinen Schwamm?", sourceObjectiveStatus = "unverified-source-field" }
quests[7728] = { id = 7728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr", description = "Folgende Gegenstände wurden gestohlen:\n\nEine Schmiedewindform.\n\nEin Ausguck-Handfernrohr.\n\nEs wurde eine Belohnung für das Zurückbringen der gestohlenen Gegenstände ausgesetzt.\n\nDie Thoriumbruderschaft ist sich sicher, dass diese Gegenstände von skrupellosen und neidischen Dunkeleisenzwergen aus der sengenden Schlucht, entwendet wurden.\n\nDas fragliche Fernrohr ist ein hervorragendes Werkzeug für Spähposten und die Schmiedeform ist schlicht unersetzlich. \n\nSolltet Ihr einen der vermissten Gegenstände finden, bringt sie zu Scrange.", sourceObjective = "Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht.\n\nDie einzigen Informationen die Ihr habt sind: Die Schmiedewindform is ein SCHMIEDEwerkzeug welches von SCHMIEDEN verwendet wird und das Ausguck-Handfernrohr ist ein unverzichtbares Werkzeug für SPÄHPOSTEN.", progress = "Wenn Ihr wegen der Belohnung gekommen seid, müsst Ihr mir zuerst die gestohlenen Gegenstände übergeben.", completion = "Fantastische Arbeit! Und nun zu Euerer Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[7729] = { id = 7729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "STELLE ZU VERGEBEN: Erledige die Konkurrenz", description = "Zuchtmeister Scrange sucht einige fähige Männer und Frauen, um seiner Konkurrenz in der sengenden Schlucht ein wenig einzuheizen.\n\nInteressierte Bewerber sollten zur sengenden Schlucht reisen und jeden Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge erschlagen, der ihnen über den Weg läuft.\n\nMeldet Euch bei Zuchtmeister Scrange, wenn Eure Kleidung ausreichend mit Blut getränkt wurde.\n\nIhr werdet schon sehen, wann sie blutig genug ist, also spart Euch jegliche Rückfragen.", sourceObjective = "Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt.", progress = "Um sicher zu gehen, werden wir Euch mit und ohne Kleidung wiegen müssen.", completion = "15,9 Pfund! Das ist dann wohl ein neuer Rekord, für Blut und Gedärme je Kleidungsstück! Gratulation, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[7730] = { id = 7730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash-Plage", description = "Schenken wir unseren angesammelten Erkundungen Glauben, so gehört der Gegner südlich der Gnolle einer insektenartigen Rasse an. Offen gesagt spielt es keine Rolle, solange sie lebendig sind. Wenn sie die Gnolle gegen uns aufhetzen, dann sind sie eine mindestens genauso große Bedrohung - wenn nicht sogar eine größere - als die Gnolle selbst.\n\nDringt tief in das Gebiet vor, in dem die Insekten der Zukk'ash hausen; auch bekannt als verwundene Tiefe. Dezimiert ihre Anzahl, berichtet mir von Euren Entdeckungen und bringt ihre Knochenpanzer als Beweis Eurer Taten zurück.", sourceObjective = "Bringt Hadoken Swiftstrider im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.", progress = "Was macht die Jagd, {name}? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Gut gemacht, {class}. Obwohl man der hohen Ausbreitung der Zukk'ash mit nichts anderem als einer wahren Invasion entgegentreten kann, so habt Ihr uns doch etwas Zeit verschafft, um eine geeignete Strategie entwickeln zu können.\n\nIch werde dafür sorgen, dass man diese Knochenpanzer untersucht; wir müssen alles über sie herausfinden, bevor wir es mit dem zu tun bekommen, was sich unglücklicherweise als eine schwerliegendere Angelegenheit als angenommen entwickelt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[7731] = { id = 7731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornstachel", description = "Einer unserer Späher berichtete, dass er während seiner Beobachtungen der verwundenen Tiefe ein riesiges Insekt - viel größer als die anderen gesichteten Insekten - gesehen habe, das durch das verschlungene Gelände umherstreifte. Es ist nicht nur größer, es scheint auch eine Art Aura abzusondern, was die anderen Insekten nicht tun. Wir haben ihm einen Namen gegeben - Zornstachel.\n\nEine Untersuchung der Innereien dieser Bestie wäre von unschätzbarem Wert, solange wir nach dem besten Weg suchen, um mit dieser Bedrohung fertig zu werden. Schneidet seine Sekretionsdrüsen heraus und bringt sie sofort zu mir zurück!", sourceObjective = "Besiegt Zornstachel in der verwundenen Tiefe und bringt seine Drüsen zu Hadoken Swiftstrider im Camp Mojache in Feralas zurück.", progress = "Habt Ihr Zornstachel bereits bezwingen können?", completion = "Beeindruckend, {class}... sehr beeindruckend! Sollte Zornstachel wirklich eine ihrer stärksten Kreaturen sein, so werden sich die Untersuchungen der Bestie mit der Zeit als sehr wertvoll erweisen. Es liegt nun an mir sicher zu stellen, dass wir uns lange genug verteidigen, um davon profitieren zu können.\n\nBitte nehmt diese Prämie als Dankeszeichen des gesamten Camps an. Danke, {name}, gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[7732] = { id = 7732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht über die Zukk'ash", description = "Ihr habt mehr als richtig gehandelt, indem Ihr Euch der Bedrohung, die die Insekten der Zukk'ash für das Camp Mojache darstellen, zugewandt habt. Die Gefahr, die von ihnen ausgeht, ist noch lange nicht vorüber. Deshalb würde Euch im Namen der Horde gerne um die Erledigung eines letzten Auftrags bitten.\n\nDies hier sind Aufzeichnungen, die alle Informationen, die wir über diese Zukk'ash erhalten haben, detailliert beinhalten. Ich möchte, dass Ihr sie zu Zilzibin Drumlore in der Gasse in Orgrimmar bringt. Er ist ein Experte, wenn es um fremde Kreaturen wie diese geht; ich hoffe er kann etwas mit dem von uns erlangten Wissen anfangen.", sourceObjective = "Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Drumlore. Er wohnt in der Gasse von Orgrimmar.", progress = "Seid gegrüßt... Ihr seht aus als wäret Ihr in wichtigen Angelegenheiten unterwegs. Kann ich Euch mit irgendetwas behilflich sein?", completion = "Ah, ich hatte es nicht anders erwartet. Diese Kreaturen, denen Ihr Euch gestellt habt... sind eine uralte Bedrohung, die die Horde weiterhin ignoriert. Es war weise von Hadoken, dass er dies - und Euch - zu mir bringen ließ.\n\nDie Zukk'ash sind nichts anderes als Kreaturen, die die Silithid genannt werden. Manch einer denkt, dass es sich dabei um unintelligente Unwesen handelt, aber lasst Euch versichern - sie sind eine weitaus schlimmere, ja sogar wesentlich schlimmere Bedrohung, als alles, was die Allianz aufbringen könnte.\n\nSolltet Ihr gewillt sein, könnte ich Eure Hilfe gebrauchen, um diese Bedrohung ans Licht zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7733] = { id = 7733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Ob Ihr es glaubt oder nicht, ich habe eine noch viel bessere Quelle für Yetibälge entdeckt! Im nördlichen Teil von Feralas, tief in der Wutschrammfeste gibt es noch andere Yetis. Diese Wesen sind noch um einiges stärker, als jene mit denen Ihr schon zu tun hattet. Also, wenn Ihr eine größere Herausforderung sucht, sind diese Biester genau das richtige für Euch.\n\nIch werde Euch grosszügig entlohnen, wenn Ihr mir 10 Wutschrammyetibälge bringt!", sourceObjective = "Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge.", progress = "Wenn diese Wutschrammyetibälge von eben so hoher Qualität sind wie ihre Gegenstücke der Wildschrammyetis, könnten sie gut und gerne so unverwüstlich wie Thorium sein!\n\nStellt Euch das einmal vor!", completion = "Exzellent, Exzellent! Ich denke diese Bälge werden Ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Hilfe, {name}. Hier, nehmt eine meiner neuesten Kreationen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7734] = { id = 7734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Ob Ihr es glaubt oder nicht, ich habe eine noch viel bessere Quelle für Yetibälge entdeckt! Im nördlichen Teil von Feralas, tief in der Wutschrammfeste gibt es noch andere Yetis. Diese Wesen sind noch um einiges stärker, als jene mit denen Ihr schon zu tun hattet. Also, wenn Ihr eine größere Herausforderung sucht, sind diese Biester genau das richtige für Euch.\n\nIch werde Euch grosszügig entlohnen, wenn Ihr mir 10 Wutschrammyetibälge bringt!", sourceObjective = "Bringt Jangdor Swiftstrider im Camp Mojache in Feralas 10 Wutschrammyetibälge.", progress = "Wenn diese Wutschrammyetibälge von eben so hoher Qualität sind wie ihre Gegenstücke der Wildschrammyetis, könnten sie gut und gerne so unverwüstlich wie Thorium sein!\n\nStellt Euch das einmal vor!", completion = "Exzellent, Exzellent! Ich denke diese Bälge werden Ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, {name}. Hier, nehmt eine meiner neuesten Kreationen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7735] = { id = 7735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Yetibalg", description = "Ihr habt einen makellosen Yetibalg gefunden, der besonders dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Pratt McGrubben in der Festung Feathermoon mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Pratt McGrubben in der Festung Feathermoon den makellosen Yetibalg.", progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Fantastisch! Es sieht so aus, als hättet Ihr die Mutter aller Yetibälge gefunden!\n\nIhr könnt Euch darauf verlassen, dass mir dieser Fund einiges Wert ist. Normalerweise zahle ich niemanden soviel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, das Ihr bei Eurem Fund an mich gedacht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[7736] = { id = 7736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub an feurigem Fluxus: Königsblut", progress = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, {race}. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Königsblut.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", completion = "Es ist immer genug Platz für einen weiteren feurigen Fluxus, Junge. Immer her damit... bis ich Euch sage, dass es genug ist." }
quests[7737] = { id = 7737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlangte Anerkennung", progress = "Ihr habt Euch erfolgreich in der Hierarchie der Bruderschaft hochgearbeitet, {race}. Wir haben begonnen, Euch mit Wohlwollen zu betrachten. Eine respektable Leistung!\n\nWenn Ihr Euch weiteren Respekt und Arbeit verschaffen wollt, hört genau zu.\n\nWir können den feurigen Fluxus noch weiter veredeln, indem wir ihm simple Dunkeleisenrückstände hinzufügen. Diese Rückstände sind hauptsächlich in den Blackrocktiefen zu finden.\n\nBringt mir alle Dunkeleisenrückstände, die Ihr finden könnt!", completion = "Je mehr Dunkeleisenrückstände, desto besser!" }
quests[7738] = { id = 7738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekter Yetibalg", description = "Ihr habt einen Yetibalg gefunden, der beinahe perfekt scheint. Euch fällt schnell auf, das dieser außergewöhnlich dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Jangdor Swiftstrider im Camp Mojache mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Jangdor Swiftstrider im Camp Mojache in Feralas den makellosen Yetibalg.", progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Dieser Fund ist einfach unglaublich! Ich glaube dies hier ist der beste Balg den ich je gesehen habe!\n\nTatsächlich wäre hier eine großzügige Belohnung angebracht. Normalerweise zahle ich niemanden soviel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, das Ihr bei Eurem Fund an mich gedacht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[7761] = { id = 7761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackhands Befehl", description = "Schwachkopf,\n\nich habe Euch immer für unfähig gehalten, Fremde daran zu hindern, den Hort unseres Herrn zu betreten. Für den sehr wahrscheinlichen Fall Eures Todes hat diese Kugel einen eingebauten Sicherheitsmechanismus der verhindert, dass sich Außenstehende direkt in den Pechschwingenhort teleportieren können.\n\nNur diejenigen, denen das Mal von Drakkisath in die Handfläche eingebrannt wurde, können die Kugel überhaupt benutzen. Glücklicherweise ist Drakkisath nicht einmal ansatzweise so inkompetent wie Ihr, Rüstmeister. Er selbst bewacht das Brandzeichen!\n\nKriegshäuptling Rend Blackhand\n\nP.S. Verbrennt diesen Brief, Idiot!", sourceObjective = "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.\n\nDem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen.", completion = "Ihr zuckt nicht einmal mit der Wimper, als Euch dass glühende Brandzeichen ins Fleisch gepresst wird. Unglaublich wie mutig Ihr seid!\n\nIhr seid nun mit dem Mal von Drakkisath gekennzeichnet. Viel Spass, beim Sturm auf die Burg!", sourceObjectiveStatus = "unverified-source-field" }
quests[7781] = { id = 7781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher von Blackrock", description = "Ihr spürt wie längst vergessene Gefühle in Euch aufflammen. Der Schmerz des Sieges hallt durch Euer Innerstes. Euch zu Füßen liegt der vom Kampf gezeichnete, gigantische Kopf von Nefarian. Bringt ihn Eurem Hochlord, großer Held!", sourceObjective = "Bringt Hochlord Bolvar Fordragon in Stormwind den Kopf von Nefarian.", progress = "Unfassbar!", completion = "Seid Ihr Euch gewahr, was Ihr da vollbracht habt, {name}? Dieser Tag wird in die Geschichte eingehen! Einen solchen Sieg hat die Allianz schon seit Jahrzehnten nicht mehr gesehen - falls überhaupt jemals!", sourceObjectiveStatus = "unverified-source-field" }
quests[7782] = { id = 7782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher von Blackrock", description = "Begebt Euch in das Tal der Helden und sprecht mit Feldmarschall Stonebridge.", sourceObjective = "Reist nach Stormwind in das Tal der Helden und sprecht mit Feldmarschall Stonebridge.", completion = "<Feldmarschall Afrasiabi verbeugt sich.>\n\nSucht Euch eine Belohnung aus und lasst die Feierlichkeiten beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7783] = { id = 7783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher von Blackrock", description = "Ihr spürt wie längst vergessene Gefühle in Euch aufflammen. Der Schmerz des Sieges hallt durch Euer Innerstes. Euch zu Füßen liegt der vom Kampf gezeichnete, gigantische Kopf von Nefarian. Bringt ihn Eurem Kriegshäuptling, großer Held!", sourceObjective = "Bringt Thrall in Orgrimmar den Kopf von Nefarian.", progress = "Ich wünschte, ich wäre mit Euch dort gewesen, {name}. Zu gerne hätte ich Nefarians Gesichtsausdruck gesehen, als er das Ende durch Eure Hand kommen sah.", completion = "Wieder einmal habt Ihr der Horde Ehre gebracht, {name}. Der Sohn von Deathwing ist tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[7784] = { id = 7784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher von Blackrock", description = "Sucht Hochfürst Saurfang im Tal der Stärke auf.", sourceObjective = "Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch.", completion = "Sucht Euch eine Belohnung aus. Anschließend werde ich den Kopf des Biests für alle sichtbar zur Schau stellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7785] = { id = 7785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Gefäßes", description = "Untersucht das Gefäß der Wiedergeburt, Sterblicher. Mit seiner Hilfe soll der Windsucher wieder auferstehen!", sourceObjective = "Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian.", progress = "Werdet Ihr ihn aus seiner ewigen Gefangenschaft befreien?", completion = "Möget auf Euren Wegen von Schutz begleitet werden. Möge der Meister Eure Bemühungen segnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7786] = { id = 7786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donneraan der Windsucher", description = "Ich habe Euch alles gesagt was ich weiß, {name}. Es ist nun Eure Aufgabe Elementium zu finden. Ihr seid es, der die körperliche Form des Feuerfürsten zerstören muss.\n\nGewinnt dadurch den Segen von Donneraan.", sourceObjective = "Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen.", progress = "Zwingt die Welt in die Knie, wenn es sein muss!", completion = "Selbst in meinen Träumen wagte ich es nicht diesen Tag vorherzusehen.\n\nSehet, Sterblicher.\n\nSEHET DEN, DER ÄLTER ALS ALLES EXISTIERENDE IST!\n\nSEHET DEN, DER SICH TITANEN UND GÖTTERGLEICHEN STELLTE!\n\nERHEBT EUCH MEISTER! BEFREIT EUCH VON EUREN FESSELN!", sourceObjectiveStatus = "unverified-source-field" }
quests[7787] = { id = 7787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerzorn erwache!", description = "Ihr habt den Windsucher bezwungen. Nehmt die schlummernde Klinge und die Materialen, die Ihr Demitrian für seinen Verrat geliefert habt, und zwingt den verlogenen Schuft, Donnerzorn zu erwecken.", sourceObjective = "Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge.", progress = "<Demitrian kauert in Eurer Gegenwart nieder.>", completion = "Ich flehe Euch an, verschont mich! Nehmt! Nehmt die Klinge! Lasst Demitrian sein erbärmliches Leben noch einmal neu angehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7788] = { id = 7788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7789] = { id = 7789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silverwing", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7790] = { id = 7790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[7791] = { id = 7791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Wolle", progress = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Stormwind einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[7792] = { id = 7792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Wolle", progress = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Darnassus einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[7793] = { id = 7793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Seide", progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, {name}!" }
quests[7794] = { id = 7794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Magiestoff", progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Stormwind nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, {name}!" }
quests[7795] = { id = 7795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Runenstoff", progress = "{name}, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten nicht unbeachtet bleiben!" }
quests[7796] = { id = 7796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Runenstoff", progress = "Seid gegrüßt, {name}! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Stormwind erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "{name} - ohne Helden, die sich wie Ihr für Stormwind einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!" }
quests[7798] = { id = 7798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spendet Seide", progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, {name}!" }
