quests[7868] = { id = 7868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket der Vorhut", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb der Warsongschlucht verwendet werden können.\n\nBewährt Ihr Euch noch weiter in der Schlucht, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7871] = { id = 7871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7872] = { id = 7872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7873] = { id = 7873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7874] = { id = 7874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silverwing", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7875] = { id = 7875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silverwing", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7876] = { id = 7876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silverwing", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7877] = { id = 7877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Shen'dralar", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.", sourceObjective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", completion = "Ihr öffnet die Truhe und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[7881] = { id = 7881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktsstiefel" }
quests[7882] = { id = 7882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktswämser", progress = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ah, Ihr habt die Wämser. Wunderbar. Darf ich fragen welches Tierleder Ihr für die Herstellung verwendet habt? Die Nähte sind erstklassig verarbeitet worden und die Struktur des Leders scheint ebenfalls sehr robust. Ihr seid ein begabter Handwerker!\n\nDankeschön, {name}, hier sind Eure Lose." }
quests[7883] = { id = 7883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der größte Gnom der Welt!" }
quests[7884] = { id = 7884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krokilisken-Junge und der bärtige Murloc", progress = "Yebb arbeitet an einer weiteren Attraktion für sein Kuriositätenkabinett. Es handelt sich dabei um eine nasse und sumpfige Behausung für einen Jungen, der von Krokilisken aufgezogen wurde und vielleicht auch für einen Murloc. Wir werden schöne, wasserdichte Beinkleider brauchen, damit  wir während dem Auf- und Abbauen nicht pitschnass werden. Schildkrötenschuppengamaschen würden sich dafür bestens eignen.\n\n{name}, könnt Ihr solche für uns anfertigen? Wenn ja, dann wird Euch ein dicker Stapel Lose des Dunkelmond-Jahrmarkts erwarten.", completion = "Klasse, Ihr habt sie hergestellt! Die werden ihren Zweck erfüllen... Ich hoffe nur, dass nicht ich es bin, der den Krokiliskenkäfig reinigen darf, wenn es soweit ist. Diese Viecher können ganz schön fies sein, findet Ihr nicht?\n\nHier Eure Lose, {name}.  Viel Spaß damit und auf dem Jahrmarkt!" }
quests[7885] = { id = 7885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungssets", progress = "Es mag Euch vielleicht nicht bewusst sein, aber die Unterhaltung eines fahrenden Jahrmarkts ist kostspielig! Alles nutzt sich so schnell ab, es ist erstaunlich, dass wir überhaupt Gewinne machen.\n\nWegen all dieser versteckten Kosten, suchen wir immer nach Möglichkeiten, wie wir unsere Ausrüstung so günstig wie möglich instandhalten lassen können. Unsere Zelte reißen zum Beispiel regelmäßig, aber ich habe gemerkt, dass Lederrüstungssets gute Flicken abgeben. Könnt Ihr mir ein paar Rüstungssets besorgen? Das würde uns den Kauf von einigen neuen Zelten ersparen! Wenn Ihr uns damit aushelfen könntet, dann würde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts erwarten...", completion = "Sehr schön! Das wird uns weiterhelfen! Ich habe gerade einen Riss im Zelt dort drüben entdeckt und eines dieser Rüstungssets ist genau das, was ich zum Flicken brauchen kann!\n\nVielen Dank, {name}. Diese Rüstungssets werden uns eine Menge an Reparaturkosten einsparen. Hier sind die Lose - Ihr habt sie Euch verdient!" }
quests[7886] = { id = 7886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdienstabzeichen" }
quests[7887] = { id = 7887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdienstabzeichen" }
quests[7888] = { id = 7888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdienstabzeichen" }
quests[7889] = { id = 7889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grober Gewichtsstein" }
quests[7890] = { id = 7890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwerer Schleifstein", progress = "Ich würde gerne einen Stab zwischen schweren Schleifsteinen befestigen und ihn dann über meinen Kopf stemmen, um mein Training zu verbessern. Es ist nicht einfach, aber man wird schließlich nicht durch bloßes Herumsitzen zur stärksten Frau der Welt - so wie ich es bin!\n\nKönnt Ihr mir helfen? Ich brauche mehr Schleifsteine - bringt mir ein paar und ich tausche sie gegen Lose des Dunkelmond-Jahrmarkts ein.", completion = "Ihr habt die Steine bekommen! Sie sind auch noch richtig schwer! Ich kann schon fühlen wie meine Muskeln anschwellen.  Danke {name}!\n\nHier, nehmt diese Lose - und achtet darauf nicht zu viele Süßigkeiten während des Jahrmarkts zu essen. Ein großer starker {class} wie ihr muss sich schließlich kämpferisch in Form halten!" }
quests[7891] = { id = 7891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Eisenarmschienen", progress = "Ich arbeite an einem neuen Kostüm für später, wenn ich einmal meinen eigenen Stand als stärkste Frau der Welt habe! Ich suche gerade nach ein paar Armschienen, die ich tragen könnte. Sie dürfen nicht zu viel bedecken, da die Leute meine Muskeln sehen möchten, aber ich möchte trotzdem etwas Farbe ins Spiel bringen, versteht Ihr?\n\nWie wäre es mit grünen Eisenarmschienen, {name}? Könnt Ihr mir solche herstellen? Wenn ja, dann hätte ich einen ganzen Haufen Lose des Dunkelmond-Jahrmarkts für Euch.", completion = "Ja! Das sind genau die Richtigen! Sie haben so eine wunderschöne Farbe und lassen meine Arme ausreichend frei, damit man sehen kann wie stark ich bin! Perfekt!\n\nHier, {name}. Hier sind Eure Lose - amüsiert Euch schön!" }
quests[7892] = { id = 7892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer schwarzer Streitkolben" }
quests[7893] = { id = 7893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituale der Stärke", progress = "{name}, in meinem Bestreben die stärkste Frau der Welt zu werden, bin ich auf meinen Reisen bereits weit umher gekommen und habe geheime Trainingstechniken von Gewichthebern, Kraftgurus und uralten Handbüchern erlernt. Ich kenne verbotene Übungen, die  Schwache töten und Unerfahrene verkrüppeln könnten!\n\nDiese Leistung von Stärke und Konditionierung erfordert ein Training mit den schwersten aller Schleifsteine überhaupt. {name}, könnt Ihr mir diese Steine besorgen oder für mich herstellen? Ich würde Euch dafür auch Lose geben...", completion = "Ich danke Euch, {name}. Ich werde diese Steine bei einem kräftebringenden Ritual verwenden, das ich von einer uralten Schrifttafel im tiefsten Dschungel des Schlingendorntals erlernt habe.\n\nMan sagt, dass derjenige, die das heilige Ritual korrekt ausführt, die Stärke und Ausdauer von zehn Tauren besitzen wird!" }
quests[7894] = { id = 7894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kupfermodulator", progress = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", completion = "Aha! Die Modulatoren! Herrlich!\n\nIch kann Euch zwar nicht genau sagen an was wir arbeiten, aber dies wird für dessen Konstruktion von unschätzbarem Wert sein. Ich stehe in Eurer Schuld, {name}, bitte, nehmt dieses Los des Dunkelmond-Jahrmarkts als Zeichen meiner Wertschätzung." }
quests[7895] = { id = 7895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrendes bronzenes Dingsda", progress = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, {name}, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", completion = "Ihr habt die Dingsdas! Wunderbar! Ich kann schon jetzt das melodische Summen und Surren in meinem Kopf hören! Oh, wenn dieser Stand erst einmal fertig ist, dann wird er ein Weltwunder sein, das mich zeichnen wird!\n\nHier sind Eure Lose, {name}. Bitte amüsiert Euch auf dem Jahrmarkt!" }
quests[7896] = { id = 7896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünes Feuerwerk", progress = "Wenn ich meinen Stand endlich fertig habe, möchte ich auch dafür werben! Was würde sich dafür schon besser eignen als Feuerwerk?\n\nNun, manch einer würde sagen, dass sich der Geruch eines Kessels, in dem die Köpfe unserer Feinde köcheln, besser zum Anziehen von Massen eignet, aber... wir sind eine gemischte Gesellschaft. Es muss also Feuerwerk sein!\n\nBringt mir grünes Feuerwerk, {name}, und ich werde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ihr habt das Feuerwerk. Wunderbare Arbeit, {name}! Ich kann nicht erwarten es zu zünden und damit allen zu sagen, dass mein Stand eröffnet ist! Ich muss noch warten, sogar noch ziemlich lange fürchte ich, aber... ich werde bereit sein, wenn ich bereit bin, richtig?\n\nHier sind die Lose, {name}. Viel Spaß!" }
quests[7897] = { id = 7897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanische Repariersets", progress = "Der hauptsächliche Grund, weshalb ich meinen Stand nicht eröffnen kann, ist... weil alles kaputt ist! Ich brauche mechanische Repariersets, um alles wieder herrichten zu können!\n\nKönnt Ihr mir diese Sets besorgen, {name}? Ich tausche sie gegen... Sets von Losen des Dunkelmond-Jahrmarkts. Was denkt Ihr?", completion = "Danke! Jetzt kann ich wieder für Ordnung sorgen.\n\nIch werde eine Menge Repariersets brauchen und oft bis spät in die Nacht arbeiten, um alles wieder zum Laufen bringen zu können.  Manchmal glaube ich, dass es besser wäre, wenn ich wieder zu meinen Wurzeln zurückkehren und meine Laufbahn als Kopfgeldjäger weiterverfolgen würde, aber... der Jahrmarkt tut mir gut.\n\nNehmt diese Lose, {name}, viel Spaß damit!" }
quests[7898] = { id = 7898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thoriumapparat", progress = "Yebb Nebblegear arbeitet wie ich an einer zukünftigen Attraktion. Nebb sagt, dass die Attraktion so aufregend ist, dass es Besucher aus der ganzen Welt anziehen wird...und uns alle sehr, sehr reich!\n\nEr meint, dass er Thoriumapparate für dieses Projekt benötigt und ich soll sie für ihn sammeln. Na, was sagt Ihr; {name}? Wisst Ihr, wo man Thoriumapparate bekommt? Solltet ihr Ingenieur sein, könntet Ihr dann welche herstellen? Wollt Ihr sie gegen Lose des Dunkelmond-Jahrmarkts einlösen?", completion = "Ah, vielen Dank {name}! Yebb wird sich über diese Apparate freuen. Ich weiß nicht, was er damit vorhat, aber Yebb ist ein cleverer kleiner Gnom. Er ist clever und vielleicht auch ein bisschen verschlagen...\n\nWenn er doch nur den Geschmack menschlichen Fleisches mögen würde, dann würde er einen großartigen Troll abgeben!\n\nHier {name}, Geschäft ist Geschäft! Diese Lose gehören Euch." }
quests[7899] = { id = 7899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine pelzige Tatzen", progress = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", completion = "Großartig, Ihr habt sie! Wir können daraus Spielsachen und anderen Schnickschack herstellen und damit bei mehr und mehr Leuten Interesse für den Jahrmarkt wecken!\n\nHier ist Euer Los, {name}.  Ihr habt es Euch verdient!" }
quests[7900] = { id = 7900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissene Bärenpelze", progress = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", completion = "Schöne Pelze, {name}! Ich werde daraus eine Menge Kuscheltiere nähen lassen. Mit Hilfe von etwas Füllmaterial und Farbe, könnte daraus eines der begehrtesten Spielsachen in ganz Azeroth werden!\n\nLose? Ach ja, Euer Entgelt!  Hier sind sie!" }
quests[7901] = { id = 7901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiche buschige Schweife", progress = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", completion = "Gut gemacht, {name}! Diese buschigen Schwänze werden unseren Besuchern gefallen - und das bedeutet sogleich glückliche Besucher... Besucher, die ihren Freunden vom Jahrmarkt erzählen und somit für noch mehr Publikum sorgen!\n\nHier sind Eure Lose! Viel Spaß auf dem Dunkelmond-Jahrmarkt... und vergesst nicht Euren Freunden von uns zu erzählen!" }
quests[7902] = { id = 7902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbenprächtige Federbüsche", progress = "Das Vorstellungsvermögen einer Person ist etwas Unglaubliches. Es kann aus einem kleinen Hügel einen riesigen Berg machen und aus einem harmlosen Schatten einen furchtbaren Alptraum!\n\nWir vom Dunkelmond-Jahrmarkt erwecken die Fantasien unserer Besucher zum Leben! Allerdings müssen wir uns manchmal schlaue Tricks einfallen lassen, um ihren Vorstellungen etwas auf die Sprünge zu helfen...\n\nIch brauche farbenprächtige Federbüsche für eine meiner Attraktionen. Ihr könnt sie von den Vögeln der etwas gefährlicheren Gegenden Azeroths bekommen. Bringt mir diese Federn und zahlreiche Lose werden Euer Eigen sein!", completion = "Ah, die Federn! Sie sind atemberaubend, findet Ihr nicht! Mit diesen Schönheiten dürfte das Entfachen der Fantasie ein einfaches sein!\n\nIhr leistet so wohltätige Arbeit, {name}. Das Leuchten in den Augen der Besucher, wenn sie unsere Attraktionen bestaunen, ist bereits ein hoher Lohn, aber bitte, nehmt auch diese Lose." }
quests[7903] = { id = 7903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Fledermausaugen", progress = "Kommt es vor, dass Ihr spät in der Nacht in einer Höhle umherwandert und nach Abenteuern sucht? Ja? Wirklich? Nun, dann habt Ihr die gruseligen Fledermausaugen gesehen, die Euch von hoch oben anstarren und nur darauf warten, dass Ihr unachtsam werdet, damit sie Euch Euer Blut aussaugen können!\n\nEin schauriger Gedanke, nicht wahr? Natürlich - Fledermausaugen sind ohne Frage gruselig!\n\nKönnt Ihr mir ein paar böse Fledermausaugen besorgen, {name}? Ich brauche sie für... für etwas, das ich entwerfe. Etwas Gruseliges.\n\nIhr könnt sie von den Fledermäusen der östlichen Pestländer bekommen.", completion = "Großartig! Ihr habt die Augen! Ich hoffe die Jagd nach den Fledermäusen war furchterregend für Euch, denn wenn sie einen mutigen {class} wie Ihr es seid ängstigen konnten, dann werden diese Augen ganz sicher auch unseren Jahrmarktsbesuchern einen Schrecken einjagen können.\n\nNehmt diese Lose, {name}, danke für Eure Dienste." }
quests[7905] = { id = 7905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelmond-Jahrmarkt", description = "Der Dunkelmond-Jahrmarkt kommt! Lasst Euch beim Besuch in Eurer Stadt nicht all die Wunder und Attraktionen entgehen!\n\nZögert nicht und Ihr werdet diesen Gutschein für kostenfreie Gewinnlose einlösen können! Bringt Euren Gutschein einfach zu Gelvas Grimgate, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan hat der Jahrmarkt seine Zelte außerhalb von Goldhain im Wald von Elwynn aufgeschlagen. Lasst Euch diese Gelegenheit nicht entgehen! Heute ist Euer Tag!", sourceObjective = "Bringt den Gutschein zu Gelvas Grimgate, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7906] = { id = 7906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelmond-Karten: Bestien" }
quests[7907] = { id = 7907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Bestienkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Bestienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Bestienkartenset zu komplettieren. Das Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[7908] = { id = 7908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Arena", description = "Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.", sourceObjective = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Short John Mithril.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[7921] = { id = 7921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdienstabzeichen" }
