quests[7935] = { id = 7935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "10 Lose - Hammel des letzten Monats" }
quests[7936] = { id = 7936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "50 Lose - Hammel des letzten Jahres" }
quests[7937] = { id = 7937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch im Osttal.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr das Holzfällerlager des Osttals im Wald von Elwynn vor Euch. Beim Fokussieren auf dieses Bild, seht Ihr einen Heuhaufen neben einem Stall.", sourceObjective = "Reist zum Holzfällerlager des Osttals im Wald von Elwynn und sucht nach Eurem Schicksal.", progress = "Dieser Heuhaufen sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Durchsuchung des Heuhaufens bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[7938] = { id = 7938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch in den Todesminen.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr die Todesminen in Westfalls Ruinen von Moonbrook. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch verwinkelte Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Minen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.", sourceObjective = "Reist zu den Todesminen in Westfall und sucht nach Eurem Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[7939] = { id = 7939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr verdichtete Schleifsteine", progress = "{name}, ich danke Euch für all Eure Hilfe. Ich kann Euch wirklich nicht genug danken!\n\nIch brauche jetzt zwar nichts mehr wirklich... aber solltet Ihr mir mehr verdichtete Schleifsteine bringen, so habe ich auch noch einige Lose des Dunkelmond-Jahrmarkts für Euch.", completion = "Nochmals danke, {name}. Viel Spaß mit diesen Losen, und erzählt Euren Freunden vom Dunkelmond-Jahrmarkt!" }
quests[7940] = { id = 7940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1200 Lose - Kugel des Dunkelmonds", progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7941] = { id = 7941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Rüstungssets", progress = "{name}, ich muss mich für all Eure Hilfe bedanken. Ich verfüge jetzt über eine Menge an Vorräten, dank Eurer Bemühungen, aber wenn Ihr mir noch mehr Rüstungssets bringen möchtet, dann werde ich sie gerne gegen ein paar Lose des Dunkelmond-Jahrmarkts eintauschen.", completion = "Hier, {name}. Ein fairer Tausch. Viel Vergnügen." }
quests[7942] = { id = 7942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Thoriumapparate", progress = "{name}, Ihr wart so gut zu uns, indem Ihr uns ohne Unterlass Waren beschafft habt. Ich bin Euch dafür unendlich dankbar!\n\nAuch wenn wir einen nicht mehr so großen Bedarf an Thoriumapparaten wie zuvor haben, so könnt Ihr mir doch jederzeit weitere bringen. Ich tausche sie dann gegen Lose des Dunkelmond-Jahrmarkts ein.", completion = "Hier, {name}. Nehmt diese Lose des Dunkelmond-Jahrmarkts und vergnügt Euch damit. Gebt sie nicht alle auf einmal aus, wie man so schön sagt!" }
quests[7943] = { id = 7943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Fledermausaugen" }
quests[7944] = { id = 7944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch in den Höhlen des Wehklagens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr eine Höhle im Südwesten von Crossroads im Brachland. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch gewundene Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Höhlen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.", sourceObjective = "Reist zu den Höhlen des Wehklagens im Brachland und sucht nach Eurem Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[7945] = { id = 7945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch außerhalb des Bleichmähnenfelsens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr den Bleichmähnenfels von Mulgore. Beim Fokussieren auf dieses Bild seht Ihr einen Baumstumpf in der Nähe des Höhleneingangs.", sourceObjective = "Reist zum Bleichmähnenfels in Mulgore und sucht nach Eurem Schicksal.", progress = "Dieser Baumstumpf sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Untersuchung des Baumstumpfs bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[7946] = { id = 7946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jubjubs Nachwuchs", progress = "Ich bin so froh, dass Jubjub wieder da ist. Die Kleine liebt Dunkeleisenbier so sehr, dass sie, als mein Vorrat zuneige ging, weggerannt ist, um mehr davon zu suchen.\n\nJetzt, da Jubjub zurück ist, versuche ich, soviel Bier wie möglich zu kriegen! Ich möchte nicht, dass sie wieder wegläuft, wisst Ihr?\n\nHabt Ihr vielleicht etwas Dunkeleisenbier dabei? Wenn ja, gebe ich Euch eines von Jubjubs Froscheiern für einen Krug Dunkeleisenbier...", completion = "Vielen Dank, {name}. Hier ist Euer Ei! Es wird noch etwas dauern bevor es ausgebrütet werden kann, doch wenn es soweit ist habt Ihr ein großartiges Haustier!" }
quests[7961] = { id = 7961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waskily Wabbits!" }
quests[7962] = { id = 7962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaninchenfelle", description = "Ich brauche einige LeCraft-Kaninchenfelle. Besorgt mir einige von den LeCrafty-Kaninchen.\n\nEine wichtige Aufgabe!", sourceObjective = "Bringt 3 LeCraft-Kaninchenfelle zu Jon LeCraft.", sourceObjectiveStatus = "unverified-source-field" }
