quests[8026] = { id = 8026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Prize Voucher" }
quests[8041] = { id = 8041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Bergs Mugamba", sourceObjective = "Seid gegrüßt, {class}. Ich bin Jin'rokh der Zerstörer, Troll von Mugamba. Wir vom Stamm der Zandalar erkennen Eure Leistungen an. Wir begrüßen Eure Hartnäckigkeit und Willenskraft.\n\nTragt diesen Talisman um Euren Hals, {class}. Lasst die Stärke des Bergs Mugamba durch Euch hindurch fließen. Fühlt die Macht, wenn Ihr unsere Feinde niederstreckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[8042] = { id = 8042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Bergs Mugamba", progress = "Gut zu sehen, dass Ihr wohlauf seid, {name}. Die glorreichen Schlachten, in denen Ihr Euch geschlagen habt, wirken sich auf das Leben des gesamten Planeten aus. Hakkar darf die Grenzen von Zul'Gurub niemals überschreiten, da die Welt seinem immensen Hunger mit Sicherheit nicht standhalten könnte.\n\nGebt mir Euren Talisman und ich werde seine Stärke noch mächtiger machen. Setzt die Stärke von Mugamba zum Bestrafen unserer Feinde ein!", completion = "Unsere Wege werden sich erneut kreuzen, {class}." }
quests[8043] = { id = 8043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Bergs Mugamba", progress = "Meister {name}, Ihr kehrt zurück! Molthor hat bereits Kunde von Euren Taten zum König geschickt. Euer Name ist sogar in den südlichen Meeren bekannt. Vielleicht werdet Ihr eines Tages ein legendärer {class} sein... eine Legende für die Ewigkeit.\n\nGebt mir Euren Talisman, damit ich seine Macht noch einmal verstärken kann.", completion = "Nutzt Eure wiedererlangte Stärke, um die Gurubashi zu vernichten!" }
quests[8044] = { id = 8044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut Mugambas", progress = "König Rastakhan sendet Euch seine Grüße, Meister {name}. Eine solche Ehre wurde noch nie jemanden zuteil, der nicht zum Stamm der Zandalar gehört.\n\n\n\nGebt mir Euren Talisman, damit ich ihn noch einmal verstärken kann. Ihr sollt wissen, dass die Wut Mugambas jetzt untrennbar mit Eurer Seele verbunden ist.", completion = "Zul'jin würde Euch beneiden, {class}. Zieht hinfort und siegt!" }
quests[8045] = { id = 8045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Emblem des Ungläubigen", sourceObjective = "Wisset, Ungläubiger: eine Katastrophe hat uns vereint. Eure heidnischen Wege werden von den Zandalarianern weder verstanden, noch geschätzt, aber wir sind ein faires Volk. Tragt dieses Emblem um Euren Hals. Es soll unseren Feinden als Warnung und den Zandalarianern als Zeichen der Freundschaft dienen.\n\nDient auch weiterhin unserem Stamm und ich werde die Macht des Emblems verstärken.", sourceObjectiveStatus = "unverified-source-field" }
